/* ÇEVİRİ pt · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("pt","olay",{
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III subiu ao trono", "00d046d9"], "d": ["Com a morte de Abdülhamid I, o sobrinho Selim III passou ao trono. Segundo o artigo Selim III da Enciclopédia do Islão da TDV, o novo sultão, que desde a sua condição de príncipe se interessava pela reforma dos exércitos europeus, pouco depois da entronização começou a mandar preparar um programa de renovação radical. Este programa seria conhecido, em poucos anos, pelo nome de Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Começou a preparação do programa de reformas do Nizâm-ı Cedîd", "eff78a68"], "d": ["Selim III mandou preparar um programa de renovação abrangente, segundo os projetos que pedira aos dignitários do Estado e a peritos estrangeiros. Segundo o artigo Nizâm-ı Cedîd da Enciclopédia do Islão da TDV, este programa não se limitou a criar um novo exército; converteu-se num vasto movimento de reforma que abrangia também as finanças, a administração provincial e a diplomacia. O programa encontraria, nos quinze anos seguintes, tanto apoiantes como opositores.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Foram criadas embaixadas permanentes nas capitais europeias", "2e9dc8a1"], "d": ["Selim III enviou pela primeira vez na história do Estado Otomano embaixadores permanentes, que desempenhariam funções contínuas, aos grandes centros europeus. Segundo o artigo Elçi da Enciclopédia do Islão da TDV, este passo dotou de uma organização duradoura a diplomacia otomana, que até então se conduzira apenas com missões temporárias e isoladas. A principal tarefa das novas embaixadas era comunicar regularmente a Istambul os desenvolvimentos políticos e militares da Europa.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Foi criado o tesouro İrad-ı Cedîd", "ae5c8ce2"], "d": ["Foi criado um tesouro separado para cobrir as despesas do exército do Nizâm-ı Cedîd e do programa de reformas. Segundo o artigo Esham da Enciclopédia do Islão da TDV, entre as receitas do novo tesouro contavam-se a exploração direta, pelo Estado, de algumas mukataas e o controlo das vendas de esham. Esta disposição foi uma tentativa de criar uma nova fonte fora do sistema financeiro tradicional.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Começou a revolta de Kabakçı Mustafa", "b98eee17"], "d": ["O descontentamento acumulado contra o Nizâm-ı Cedîd rebentou com a sublevação dos soldados yamak sob a liderança de Kabakçı Mustafa. Segundo o artigo Kabakçı İsyanı da Enciclopédia do Islão da TDV, os rebeldes tomaram em pouco tempo o controlo de Istambul e exigiram as cabeças dos dignitários favoráveis ao Nizâm-ı Cedîd. A sublevação resultou, em poucos dias, na deposição de Selim III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III foi deposto", "ff2c30ec"], "d": ["Sob a pressão da revolta de Kabakçı Mustafa, Selim III foi deposto por uma fetva obtida do xeique do Islão (şeyhülislam). Segundo o artigo Selim III da Enciclopédia do Islão da TDV, esta decisão foi o momento em que terminou de facto o período de reformas de dezoito anos; o exército do Nizâm-ı Cedîd foi também dissolvido em pouco tempo. Selim passou a ser mantido sob vigilância no Palácio de Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV subiu ao trono", "8f1ac86c"], "d": ["Logo a seguir à deposição de Selim III, o sobrinho Mustafa IV foi proclamado sultão. Segundo o artigo Mustafa IV da Enciclopédia do Islão da TDV, o novo sultão iniciou o sultanato sob a influência dos meios contrários ao Nizâm-ı Cedîd que tinham apoiado a revolta. Este período, de curta duração, foi uma fase de instabilidade em que a autoridade central se enfraqueceu por completo.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Paxá entrou em Istambul com o seu exército", "0cad3dea"], "d": ["O âyan de Ruse, Alemdar Mustafa Paxá, chegou diante de Istambul com o seu exército com o fim de repor Selim III no trono. Segundo o artigo Alemdar Mustafa Paşa da Enciclopédia do Islão da TDV, a sua entrada na cidade foi recebida pessoalmente por Mustafa IV; mas, em poucos dias, o equilíbrio de poder dentro do palácio mudaria por completo. Esta entrada iniciou a cadeia de acontecimentos que resultou tanto na morte de Selim como numa nova entronização.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III foi morto", "e452f5f6"], "d": ["No dia em que Alemdar Mustafa Paxá tomou a Sublime Porta, Selim III foi morto no palácio por ordem de Mustafa IV. Segundo o artigo Selim III da Enciclopédia do Islão da TDV, foi uma decisão tomada para evitar a tentativa de repor no trono um sultão deposto. A morte de Selim resultou, no mesmo dia, na entronização de Mahmud.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II subiu ao trono", "661c1974"], "d": ["Depois do assassinato de Selim III, Mahmud, único membro masculino que restava da dinastia, subiu ao trono com o apoio de Alemdar Mustafa Paxá. Segundo o artigo Mahmud II da Enciclopédia do Islão da TDV, o novo sultão passou os primeiros meses do seu sultanato sob a tutela de Alemdar, que o pusera no trono, e no esforço de restabelecer o equilíbrio entre os âyans e o centro. Este período foi o início do processo de reforma radical dos vinte anos seguintes.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Foi criado o exército Sekbân-ı Cedîd", "6f9eb5e4"], "d": ["Alemdar Mustafa Paxá mandou criar, em lugar do dissolvido Nizâm-ı Cedîd, um novo exército equipado à europeia. Segundo o artigo Sekbân-ı Cedîd da Enciclopédia do Islão da TDV, esta força, formada por três regimentos, foi vista pelos janízaros como uma ameaça direta e foi eliminada, apenas alguns meses após a sua criação, numa revolta de janízaros.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["A queda de Ibraila — a primeira grande brecha na linha do Danúbio", "ee519321"], "d": ["Na guerra com a Rússia iniciada em 1806, a fortaleza de Ibraila, na margem norte do Danúbio, foi cercada e bombardeada pelas forças russas comandadas pelo conde Kamenski. No interior havia 4100 infantes, 1100 cavaleiros e 260 canhões; a fortaleza rendeu-se ao general Essen por falta de víveres. A extremidade norte da linha de defesa do Danúbio ficou assim aberta.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["A rendição de Ruse — a margem sul do Danúbio também se perde", "084062e8"], "d": ["Ruse resistiu ao longo e sangrento cerco do exército russo comandado pelo conde Kamenski; rendeu-se com a condição de que a guarnição e a população civil abandonassem a cidade em segurança. A queda da mais forte cidade-fortaleza da margem sul do Danúbio inverteu o curso da guerra a favor da Rússia.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Foi criado o Corpo Eşkinci", "67c56759"], "d": ["Mahmud II mandou criar uma nova unidade, a receber instrução à europeia, com soldados escolhidos de entre o corpo dos janízaros. Segundo o artigo Eşkinci Ocağı da Enciclopédia do Islão da TDV, a unidade começou a instrução a 12 de junho de 1826, mas os janízaros viram nisso o fim do seu próprio corpo. A revolta que rebentou três dias depois pôs termo também à curta vida do Corpo Eşkinci.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Foi criado o Asâkir-i Mansûre-i Muhammediyye", "14b84a7e"], "d": ["Logo a seguir à abolição do Corpo dos Janízaros, Mahmud II mandou criar, em seu lugar, um novo exército regular e com instrução à europeia. Segundo o artigo Asâkir-i Mansûre-i Muhammediyye da Enciclopédia do Islão da TDV, este exército, com a sua ordem de postos, o seu programa de instrução e o seu sistema de soldos, converteu-se, ao contrário das tentativas anteriores, numa instituição duradoura. O exército transformar-se-ia, nos anos seguintes, no exército Nizâmiye da época do Tanzimat.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["A confraria Bektashi foi encerrada", "f7d9a367"], "d": ["Em simultâneo com a abolição do Corpo dos Janízaros, foi também proibida a confraria Bektashi, conhecida pelos laços religiosos com o corpo. Segundo o artigo Bektaşîlik da Enciclopédia do Islão da TDV, enquanto alguns xeiques de pequenos tekke foram executados, o xeique da dergâh de Hacı Bektaş foi exilado para Amasya e os tekke foram entregues à administração Nakşibendî. A confraria, apesar deste duro golpe, manteve a sua organização de forma secreta.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["O incidente do leque — o pretexto da ocupação", "e949001e"], "d": ["Numa reunião tornada tensa pelo não pagamento da antiga dívida de cereais da França à Argélia, o dei Hüseyin bateu com o leque que tinha na mão no cônsul francês Deval. Este incidente, nascido de uma disputa de créditos, foi feito o pretexto oficial da ocupação que começaria três anos depois.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["O bloqueio francês da costa de Argel — o cerco de três anos", "d0ba97a5"], "d": ["Depois do incidente do leque, a França bloqueou a costa argelina. O bloqueio durou três anos; o comércio marítimo e as fontes de receita da milícia (ocak) secaram e a sua capacidade de resistência foi corroída antes de começar a ocupação.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["O Tratado de Turkmenchay: a passagem de Erevan e Talysh para a Rússia", "abffcfdb"], "d": ["Quando a guerra russo-persa de 1826-1828 terminou com uma pesada derrota do Irão, pelo tratado assinado em Turkmenchay os canatos de Revan e Nakhichevan e a região de Talysh (Lenkoran, Astara), na costa do Cáspio, foram cedidos à Rússia; foi imposta também uma pesada indemnização de guerra. Segundo o artigo Revan da Enciclopédia do Islão da TDV, esta perda é o momento em que foi traçada a fronteira russo-persa no Cáucaso, de modo a manter-se em grande parte válida até hoje, e desencadeou também a emigração da população arménia para Revan.", "f6438d89"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["A segunda queda de Ibraila — o czar Nicolau diante da fortaleza", "eb6a8741"], "d": ["Ibraila, devolvida aos otomanos em 1812 e novamente fortificada em 1817-1818, foi cercada em abril, tendo no interior 4000 guardas e 278 canhões. O seu guarda Ebûbekir Paxá estabeleceu uma nova linha de defesa; o czar Nicolau I chegou pessoalmente diante da fortaleza no fim de maio. A cidade sofreu a ocupação russa, mas seria devolvida pelo Tratado de Edirne e deixada ao principado da Valáquia.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["A proclamação do fez como chapéu oficial", "f55be4eb"], "d": ["Mahmud II, fazendo uma mudança radical no vestuário dos funcionários e dos soldados, proclamou o fez como cobertura de cabeça oficial, em lugar do turbante. Segundo o artigo Fes da Enciclopédia do Islão da TDV, esta decisão foi anunciada por um hatt-ı hümâyun e posta em prática juntamente com as reformas de estilo ocidental do Asâkir-i Mansûre-i Muhammediyye. A mudança significava também o fim da hierarquia tradicional do vestuário.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["A cedência de Ahıska à Rússia — o centro da província de Çıldır perde-se", "e2e00b2a"], "d": ["Ahıska, que estava sob administração otomana desde a Batalha de Çıldır de 1578 e fora centro da província de Çıldır, foi cedida à Rússia pelo Tratado de Edirne, assinado no fim da guerra de 1828-1829. A perda da cidade criou profunda tristeza entre o povo e foi tema de muitas elegias.", "9ad8078a"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["O desembarque de Sidi Ferruch — o exército francês em solo argelino", "33327553"], "d": ["Depois do bloqueio de três anos, o exército francês de desembarque comandado pelo conde de Bourmont desembarcou tropas na baía de Sidi Ferruch, a oeste de Argel. As forças que avançavam para a cidade romperam em três semanas a linha de defesa; a 4 de julho caiu o Forte do Imperador, que domina a cidade, e no dia seguinte o dei Hüseyin rendeu-se.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["O exílio do dei Hüseyin — o fim de facto da milícia (ocak) de Argel", "e122403b"], "d": ["Em virtude das condições de rendição, o último dei de Argel, Hüseyin, foi retirado da cidade com a família e o tesouro e enviado para Nápoles. A administração da milícia (ocak), que se ligara a Selim II em 1519 e fora durante trezentos anos a mais forte base naval otomana no Mediterrâneo, terminou assim.", "54846340"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["A retirada do exército russo da Valáquia e da Moldávia — o fim da ocupação de seis anos", "efdb0275"], "d": ["Na guerra otomano-russa de 1828-1829, os russos tinham ocupado a Valáquia e a Moldávia e, depois do Tratado de Edirne, não se tinham retirado até que a indemnização de guerra fosse paga. Em janeiro de 1834, quando a indemnização foi reduzida a cinco milhões, as forças russas evacuaram os Principados e foram nomeados novos voivodas para os dois principados. A suserania otomana voltou no papel, mas a Rússia manteve a influência que estabelecera com o Règlement Organique.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Foi criada a organização Redif-i Asâkir-i Mansûre", "15947493"], "d": ["A organização Redif, como força de reserva que apoiaria o Asâkir-i Mansûre-i Muhammediyye, foi criada pelo regulamento de 8 de julho de 1834. Segundo o artigo Redif da Enciclopédia do Islão da TDV, sob a direção do serasquer Koca Hüsrev Paxá, formaram-se nos distritos provinciais batalhões de cerca de mil e quatrocentos homens cada. A organização foi concebida para apoiar também a segurança local sem ser posta em serviço permanente.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Foi criado o Ministério dos Negócios Estrangeiros", "750c6c7d"], "d": ["Mahmud II, abolindo o cargo de Reisülküttâb, que conduzia os negócios estrangeiros, criou em seu lugar o Hariciye Nezareti. Segundo o artigo Hariciye Nezâreti da Enciclopédia do Islão da TDV, para o primeiro ministério do novo nezaret foi posto Mehmed Âkif Paxá e a organização começou a funcionar na mansão do embaixador em Viena, Rıfat Bey. Esta disposição foi o início da condução da política externa otomana segundo o princípio do ministério moderno.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Foi criado o Meclis-i Vâlâ-yı Ahkâm-ı Adliyye", "69db056e"], "d": ["Mahmud II mandou criar o Meclis-i Vâlâ-yı Ahkâm-ı Adliyye como conselho de alto nível em que se discutiriam as leis e os regulamentos a preparar. Segundo o artigo Meclis-i Vâlâ-yı Ahkâm-ı Adliyye da Enciclopédia do Islão da TDV, o conselho começou de facto a funcionar a 31 de março de 1838 e quase todas as reformas posteriores do Tanzimat foram preparadas e fiscalizadas através deste órgão. A instituição converteu-se num dos mais importantes centros da burocracia otomana moderna.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["O Assalto a Sinope", "5947e93f"], "d": ["A frota russa do mar Negro, sob o comando do almirante Nakhimov, atacou sem declaração de guerra a frota otomana fundeada no porto de Sinope; afundaram-se doze navios, mais de dois mil soldados caíram como mártires e o comandante da frota, Osman Paxá, foi feito prisioneiro. Segundo o artigo Sinop da Enciclopédia do Islão da TDV, no assalto arderam também na cidade sete mescides, duas escolas, 247 casas e 170 lojas, e perderam a vida civis, cinco muçulmanos e dezasseis cristãos. O caso, que ecoou na opinião pública europeia como o 'desastre de Sinope', foi o desencadeador direto da entrada da Inglaterra e da França na guerra, ao lado dos otomanos, em poucos meses.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Foi publicado o Tasvir-i Efkâr", "506c98e2"], "d": ["O Tasvir-i Efkâr, publicado por Şinasi, começou a sair como o quarto jornal turco, depois de Takvîm-i Vekāyi', Cerîde-i Havâdis e Tercüman-ı Ahvâl. Segundo o artigo \"Tasvîr-i Efkâr\" da TDV, o jornal tornou-se, no tempo de Nâmık Kemal, que viria a assumir a chefia de redação, o porta-voz do movimento dos Novos Otomanos.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Foi fundada a Sociedade dos Novos Otomanos", "335fb02d"], "d": ["Os intelectuais otomanos que fugiram para a Europa, sob a liderança de Mustafa Fâzıl Paxá, organizaram-se com um regulamento de treze artigos sob o nome de Jovem Turquia. Segundo o artigo \"Yeni Osmanlılar Cemiyeti\" da TDV, o grupo difundiu a exigência de governo constitucional publicando em Paris, Londres e Genebra jornais como Muhbir e Hürriyet.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Foi criado o Şûrâ-yı Devlet", "b863b306"], "d": ["O Meclis-i Ahkâm-ı Adliyye foi dividido em dois, criando-se o Şûrâ-yı Devlet, que tratava dos assuntos administrativos, e o Dîvân-ı Ahkâm-ı Adliyye, que cuidava dos assuntos judiciais. Segundo o artigo \"Şûrâ-yı Devlet\" da TDV, para a primeira presidência da instituição, que tomou por modelo o Conseil d'État francês, foi posto Midhat Paxá; o objetivo era a separação do legislativo, do executivo e do judicial.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Saiu a ordem de fundação do Darülfünun", "513704bf"], "d": ["Com a ordem preparada pelo grão-vizir Âli Paxá e pelo ministro da Instrução Saffet Paxá, o Darülfünun foi oficialmente fundado; as primeiras aulas já tinham começado em 1863. Segundo o artigo \"Darülfünun\" da TDV, a instituição passou de facto ao ensino em fevereiro de 1870, sob a direção de Hoca Tahsin Efendi, com os ramos de filosofia-letras, ciências e direito.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Começaram os trabalhos da Mecelle-i Ahkâm-ı Adliyye", "8abdcbee"], "d": ["A Sociedade da Mecelle, formada sob a presidência de Ahmed Cevdet Paxá, presidente do Dîvân-ı Ahkâm-ı Adliyye, empenhou-se na preparação de um código civil baseado no direito hanafita. Segundo o artigo \"Mecelle-i Ahkâm-ı Adliyye\" da TDV, o último fascículo da obra, composta por dezasseis livros e 1851 artigos, foi concluído e entrou em vigor a 15 de setembro de 1876; é considerada a primeira forma codificada do direito islâmico.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["Foi representada \"Pátria ou Silistria\", Nâmık Kemal foi enviado para o exílio", "3861284c"], "d": ["Quando a peça de tema patriótico de Nâmık Kemal foi representada no Teatro de Gedikpaşa, os espectadores saíram às ruas gritando \"Viva a pátria, viva Kemal\". Segundo o artigo \"Nâmık Kemal\" da TDV, o governo, assustado com esta manifestação, encerrou o jornal İbret e a 6 de abril de 1873 enviou Nâmık Kemal, sem julgamento, para o exílio em Chipre (Famagusta).", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Abdülaziz morreu em circunstâncias suspeitas", "85816692"], "d": ["Abdülaziz, que depois de deposto fora, por sua própria vontade, transferido para o Palácio de Feriye (1 de junho de 1876), foi encontrado a 4 de junho no seu quarto com as veias dos pulsos cortadas. Uma junta de dezanove médicos, em que figuravam também médicos das embaixadas, preparou um relatório de redação ambígua; a morte foi anunciada nos jornais a 6 de junho como suicídio. O inquérito mandado abrir por Abdülhamid II chegou, em contrapartida, à convicção de que a morte não fora suicídio, mas assassinato, e os acusados foram julgados em 1881 no Tribunal de Yıldız; a questão é ainda hoje discutida na historiografia.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["A destituição e o exílio de Midhat Paxá do grão-vizirado", "b5247b06"], "d": ["O grão-vizir Midhat Paxá, arquiteto do Kanun-i Esasi, foi destituído por Abdülhamid II seis semanas depois da sua proclamação e enviado para o exílio no estrangeiro numa só noite. Segundo o artigo Midhat Paşa da Enciclopédia do Islão da TDV, a destituição é associada ao desagrado do sultão com as disposições da constituição que limitavam os seus poderes. O paxá foi primeiro a Nápoles e depois a várias cidades da Europa.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["A recuperação de Riade aos Reşîdîs por Abdülazîz b. Suûd", "75eb8830"], "d": ["O jovem Abdülazîz, da dinastia Saud, que dez anos antes fora para o exílio no Kuwait, com um pequeno destacamento atacou de surpresa Riade, matou o vice-governador do Âl-i Reşîd (Shammar) e tomou a cidade. Segundo o artigo Riyad da Enciclopédia do Islão da TDV, o enfraquecimento progressivo dos Reşîdîs e o facto de não poderem enviar reforços à cidade facilitaram o êxito do ataque; o caso é considerado o momento da fundação do Segundo Estado Saudita, que nos trinta anos seguintes formaria o núcleo da atual Arábia Saudita.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["A entrada do Exército de Ação em Istambul", "41c8304c"], "d": ["O Exército de Ação, que partiu de Salónica e era formado em maioria por unidades ligadas ao Comité de União e Progresso, entrou em Istambul para reprimir a revolta de 31 de Março. Segundo o artigo Hareket Ordusu da Enciclopédia do Islão da TDV, o comando foi assumido por Mahmud Şevket Paxá e a chefia do estado-maior foi exercida pelo capitão Mustafa Kemal. Depois de breves combates, a ordem foi restabelecida na cidade.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["A dissolução da última Assembleia dos Deputados Otomana", "2b709269"], "d": ["Depois de Istambul ter sido oficialmente ocupada pelas forças da Entente e de muitos deputados terem sido presos, a Assembleia dos Deputados ficou impossibilitada de trabalhar e foi oficialmente dissolvida pela vontade de Mehmed VI. Segundo o artigo Meclis-i Mebusan da Enciclopédia do Islão da TDV, esta dissolução simbolizou o fim de facto da tradição parlamentar constitucional otomana. O encerramento reforçou a necessidade de reunir em Ancara uma nova assembleia nacional.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["A abertura da Grande Assembleia Nacional da Turquia", "6eab539d"], "d": ["Depois da dissolução da Assembleia dos Deputados em Istambul, os deputados reuniram-se em Ancara e abriram a Grande Assembleia Nacional da Turquia, e Mustafa Kemal Paxá foi eleito presidente da assembleia. Segundo o artigo Türkiye Büyük Millet Meclisi da Enciclopédia do Islão da TDV, a assembleia teve um caráter extraordinário, reunindo em si poderes legislativos e executivos. Esta abertura foi o ponto de viragem em que o centro político e institucional da luta nacional se deslocou para Ancara.", "805871d7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["A conquista da fortaleza de Zvornik", "657c465a"], "d": ["A fortaleza de Zvornik, na margem do Drina, foi conquistada pelos otomanos em 1460. Segundo a Enciclopédia do Islão da TDV, devido à sua posição favorável do ponto de vista administrativo e militar, foi feita primeiro centro de kaza, em 1480 transformada em centro do sanjaco com o mesmo nome e, em 1491, fortificada com muralhas de pedra e convertida, com as suas seis mesquitas, oito tekke e banhos, num importante centro administrativo-comercial.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["A morte de Kâsım Han, a subida ao trono de Danyal Han (Canato de Kasım)", "522fd0fd"], "d": ["Com a morte do fundador do canato, Kâsım Han, em 873/1468, sucedeu-lhe o filho Danyal; Danyal reinou até 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["A Batalha Naval de Diu — a supremacia de Portugal no oceano Índico", "1778d347"], "d": ["A frota de Melik Ayaz, que governava a região em nome do Sultanato do Guzerate, apoiada pelos mamelucos, sofreu uma pesada derrota ao largo de Diu perante a esquadra do governador-geral português Francisco de Almeida, que procurava estabelecer bases de abastecimento nestas costas. Esta derrota deu a Portugal uma supremacia naval duradoura no oceano Índico e quebrou o poder naval mameluco-guzerate; é considerada o início do desequilíbrio de forças que forma o pano de fundo da luta no mar Vermelho e no oceano Índico que os otomanos herdaram depois de 1517 (a defesa de Jidá, o cerco de Diu de 1538).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["A revolta de Kalender Xá", "f60f6ca4"], "d": ["Com as dificuldades financeiras na Anatólia, o descontentamento com as novas disposições administrativas e o efeito da propaganda safávida, grandes tribos turcomanas como as Çiçekli, Akça Koyunlu, Masadlı e Bozoklu, juntamente com grupos que restavam da anterior revolta de Baba Zünnûn, reuniram-se à volta de Kalender Xá e atingiram uma força de cerca de trinta mil pessoas. Os rebeldes derrotaram primeiro o beylerbeyi de Rum; com o grão-vizir Makbul İbrâhim Paxá a reunir soldados e a prometer-lhes direitos, o apoio a Kalender dissolveu-se e a revolta foi reprimida na região de Elbistan; Kalender Xá e Veli Dündar foram mortos em junho de 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["A conquista de Şehrizor — a tomada da fortaleza de Zalm", "4320d9b8"], "d": ["Durante a campanha de Nakhichevan do Legislador, o beylerbeyi de Bagdade Osman Paxá fora encarregado de tomar a região de Şehrizor; Baltacı Mehmed Paxá, que se tornou beylerbeyi de Bagdade com a morte dele, cercou Zalm, a fortaleza central da região, e tomou-a a 22 de agosto de 1554 (23 de Ramazan de 961). Assim, a bacia de Şehrizor, na vertente ocidental do Zagros, entrou na administração otomana e a ligação entre Bagdade e o Curdistão ficou assegurada; a região foi primeiro feita sanjaco e dada a Murad Bey. Em 1563, o beylerbeyi Muzaffer Paxá construiu como novo centro de província a fortaleza de Gülanber; a fortaleza seria demolida em 1623 por ordem do xá Abbas e reconstruída em 1638, no tempo de Hüsrev Paxá.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["A conversão ao cristianismo do soberano do Canato de Kasım e a sua remoção do canato", "a1a8eeb9"], "d": ["O soberano à frente do canato tomou o nome de 'Semen (Simeão)' e fez-se cristão; os russos, tendo em conta a reação dos súbditos muçulmanos, retiraram-no do canato. Esta pessoa foi pouco depois proclamada por Ivan, o Terrível, soberano nominal em Moscovo com o título de 'grão-príncipe do czar e da Rússia' (1575) — o cruzamento mais impressionante entre o Canato de Kasım e o trono de Moscovo.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["A ligação do sanjaco de Fezzan a Trípoli de Barbaria — Murzuk e a encruzilhada de caravanas do Saara", "2e6554a4"], "d": ["Em resultado da pressão do beylerbeylik de Trípoli de Barbaria, Fezzan, encruzilhada de caravanas do Saara, aceitou a sujeição otomana, com centro em Murzuk. Segundo o artigo Fizan da Enciclopédia do Islão da TDV, a dinastia Evlâd-ı Muhammed, que governava a região, foi deixada livre nos seus assuntos internos com a condição de pagar um imposto regular; Fezzan foi organizado como sanjaco dependente da província de Trípoli, tomada em 1551. Assim, o comércio de escravos, ouro e camelos na linha Trípoli-Murzuk-Bornu entrou sob controlo otomano. Esta administração indireta passaria em 1711 para as mãos dos Karamanlı e, em 1842, para a organização direta de kaza.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["A entrada de Nakhichevan e Ordubad na administração otomana", "24d939b3"], "d": ["Depois da tomada de Revan em 1583 e de ser feita centro de beylerbeylik, as forças que desceram para sudeste ao longo do vale do Aras ligaram Nakhichevan e Ordubad à administração otomana; as duas cidades tornaram-se sanjacos da recém-criada província de Revan. Segundo o artigo Nahcıvan da Enciclopédia do Islão da TDV, a primeira administração otomana duradoura na cidade foi estabelecida durante esta guerra — na campanha de Nakhichevan de 1553 a cidade fora tomada, mas apenas saqueada e abandonada. Assim, abriu-se a estrada militar entre Revan e Tabriz e foi possível entrar em Tabriz em setembro do mesmo ano. O xá Abbas retomaria Nakhichevan em 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["A revolta de Deli Hasan Paxá e o seu apaziguamento com o beylerbeylik da Bósnia", "144f3f2d"], "d": ["Deli Hasan, irmão que se pôs à frente do movimento depois da morte, em 1602, do líder celali Karayazıcı Abdülhalim, aproveitando a liberdade de movimentos que as guerras austríacas em curso davam aos grupos celalis, invadiu Kütahya e marchou sobre Afyonkarahisar. Neste período em que o Estado lidava ao mesmo tempo com as frentes austríaca e persa, a questão foi resolvida 'com brandura': dando a Deli Hasan o posto de paxá e o beylerbeylik da Bósnia, o movimento de revolta foi oficialmente encerrado em 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["A tomada da cidade de Kasım pelas forças russas, Uraz Muhammed Han", "b3f0bd34"], "d": ["Como reflexo do Tempo das Perturbações (Smuta) na Rússia, as forças russas cercaram e tomaram a cidade de Kâsım, passando a fio de espada a maior parte da sua população. Uraz Muhammed, que estava à frente do canato, fora visado por apoiar o Falso Dimitri II; no ano seguinte (1610) foi também morto numa conspiração.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["A perda da fortaleza de Azak para os cossacos do Don", "ba068b2f"], "d": ["Os cossacos do Don tomaram dois meses depois a fortaleza de Azak, que tinham cercado a 21 de abril de 1637; a fortaleza, porta nordeste do mar Negro e chave do comércio do Don, saiu pela primeira vez das mãos dos otomanos. Segundo o artigo Azak da Enciclopédia do Islão da TDV, os cossacos tomaram a fortaleza em 1637, resistiram em 1641 ao grande cerco de três meses comandado por Deli Hüseyin Paxá e só em 1642, com a chegada do cã da Crimeia Mehmed Giray, evacuaram a fortaleza. O Estado estava então ocupado com a frente de Bagdade; o facto de a fortaleza não ter podido ser mantida por cinco anos é a primeira fissura na qualidade de 'lago otomano' do mar Negro.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["A reconquista de Lemnos e Samotrácia", "c445553b"], "d": ["Depois da libertação de Tenedos a 31 de agosto de 1657, Köprülü Mehmed Paxá orientou a frota para norte e retomou Lemnos e Samotrácia, que Veneza detinha havia dezasseis meses. Segundo o artigo Limni da Enciclopédia do Islão da TDV, a ilha caíra nas mãos de Veneza em julho de 1656 e foi retomada em novembro de 1657. Assim, o bloqueio veneziano na entrada do estreito de Çanakkale foi totalmente quebrado e a rota dos cereais de Istambul voltou a ficar segura; é o ganho mais concreto do primeiro ano em que o grão-vizir chegou com poderes extraordinários.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["A perda de Knin para Veneza — caiu a fortaleza de fronteira da Dalmácia, de 166 anos", "252406b7"], "d": ["Na guerra aberta em várias frentes depois do desastre de Viena de 1683, as forças venezianas avançaram para o interior da Dalmácia. Knin, cercada pelo general da Dalmácia Girolamo Cornaro, foi entregue pelo beylerbeyi Mehmed Paxá depois de um cerco de doze dias. Knin era a fortaleza-chave da linha de fronteira da Dalmácia que Gazi Hüsrev Bey conquistara em 1522 e que durante 166 anos esteve nas mãos otomanas; a sua perda abriu em grande parte a região a Veneza.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["A reconquista de Bassorá à ocupação persa", "5b10c5c1"], "d": ["Bassorá, que Sâdık Han, irmão de Kerim Han Zend, tomara em 1776, foi evacuada quando, depois da morte de Kerim Han a 2 de março de 1779, começou no Irão a luta pelo trono; Sâdık Han voltou ao Irão com a pretensão ao sultanato. A cidade ficou por um breve período nas mãos da tribo dos Müntefik e depois voltou à administração otomana. O antigo mütesellim Süleyman Ağa, regressado de Xiraz, pediu o governo de Bassorá e tornou-se, com o nome de Büyük Süleyman Paxá, governador de Bassorá, Bagdade e Şehrizor. O comércio do golfo voltou ao controlo otomano; nos anos da ocupação, parte do comércio deslocara-se para o Kuwait e, desde 1778, também o correio do deserto saía do Kuwait.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["A morte de Timur Xá, a entronização de Zaman Xá (Estado Durrani)", "c3effdb2"], "d": ["Com a morte de Timur Xá, que durante mais de vinte anos consolidou o país por dentro, os três irmãos governadores de Kandahar-Herat-Cabul disputaram o trono; Zaman Xá, governador de Cabul, que detinha a capital, tornou-se xá a 20 de maio de 1793. Esta crise sucessória é, de facto, o início do processo de fragmentação da dinastia.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — o fim do sistema tradicional kapu no Havai", "0b10e1d8"], "d": ["Seis meses depois da morte de Kamehameha I, o novo rei Liholiho, com o apoio da mãe Kaʻahumanu, violou deliberadamente a proibição de homens e mulheres comerem separados (ʻaikapu). Este ato, conhecido por 'ʻAi Noa' (refeição livre), pôs oficialmente termo ao tradicional sistema religioso-jurídico kapu; os antigos templos (heiau) das ilhas foram em pouco tempo demolidos. É a maior rutura religioso-política anterior à chegada dos missionários ocidentais (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["O Protocolo de Londres — o reconhecimento da independência da Grécia", "4c7b4b72"], "d": ["O protocolo assinado em Londres pela Inglaterra, França e Rússia, ultrapassando a autonomia prevista pelo Tratado de Edirne, reconheceu a Grécia como Estado INDEPENDENTE. Disposições: a península da Moreia, a Ática e Negroponte, com as ilhas Cíclades, foram deixadas ao novo Estado; a fronteira foi traçada na linha Arta-Volos; decidiu-se o pagamento de uma indemnização ao Estado Otomano; a forma de governo do Estado foi determinada como 'monarquia independente'. Foi o PRIMEIRO Estado independente separado do império e estabeleceu o modelo jurídico das independências balcânicas seguintes.", "e8fc6290"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah b. Reşîd tomou o emirado de Hail — a fundação da dinastia Shammar (Reşîdî)", "fb513b8a"], "d": ["Com a queda de Dir'iyye às forças de Mehmed Ali Paxá em 1818, a região de Jabal Shammar saiu do domínio saudita e o emirado ficou nas mãos da família Ibn Ali. Abdullah b. Reşîd, que apoiava o restabelecimento do domínio otomano, ganhou em 1835, com o irmão Ubeyd, a luta que travou contra a família Ibn Ali, tomou o emirado de Hail e estabeleceu o domínio da dinastia Reşîdî.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Foi proclamada a primeira constituição escrita do Havai", "401a8a1d"], "d": ["Foi proclamada a primeira constituição inteiramente escrita do reino; este documento, que limitava o poder do rei e instituía uma assembleia representativa, transformou o Havai numa monarquia constitucional.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["A Constituição da Baioneta — os poderes do rei Kalākaua foram cerceados", "4953363b"], "d": ["Um grupo de milícia armada ameaçou o rei Kalākaua e forçou-o a assinar uma nova constituição que cerceava em grande parte os poderes da monarquia; o documento é conhecido como 'Constituição da Baioneta' (Bayonet Constitution) e pôs o trono de facto sob o controlo da elite colona branca.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["A morte de George Tupou I, a subida ao trono de George Tupou II (Tonga)", "b56e2b32"], "d": ["Com a morte do rei fundador George Tupou I, passou ao trono o bisneto George Tupou II; a cerimónia de coroação realizou-se a 17 de março de 1893 em Nukuʻalofa.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["A Nova Zelândia tornou-se o primeiro país autogovernado a conceder o voto às mulheres", "0d277cde"], "d": ["Com a nova Lei Eleitoral assinada pelo governador Lord Glasgow, a Nova Zelândia tornou-se o primeiro país autogovernado do mundo a conceder às mulheres o direito de voto nas eleições parlamentares.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Foi proclamada a República do Havai", "4346bd5d"], "d": ["Os conspiradores que em 1893 derrubaram a rainha Liliuokalani converteram o governo provisório numa república formal; Sanford Dole foi proclamado presidente. Este regime intermédio durou até à anexação pelos EUA em 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["As fronteiras da Nova Zelândia alargaram-se de modo a abranger as ilhas Cook e Niue", "d0370a33"], "d": ["As fronteiras da Nova Zelândia foram alargadas de modo a abranger as ilhas Cook (Rarotonga, Aitutaki e as ilhas do sul, e as ilhas Cook do norte) e Niue; estas ilhas passaram a ser território dependente da Nova Zelândia.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["A morte de George Tupou II, a subida ao trono de Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II morreu de tuberculose; a filha de 18 anos, Sālote, foi proclamada rainha no dia seguinte e a cerimónia de coroação realizou-se a 11 de outubro de 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["Foi proclamada a República Popular de Khwarazm", "0a6b79f9"], "d": ["Depois da derrubada do cã de Khiva, a seguir à Revolução de Outubro de 1917, foi proclamada a República Popular de Khwarazm.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["O Tratado de Sèvres — o texto da partilha do império", "64980d7b"], "d": ["O texto que o governo otomano assinou com as potências da Entente e que liquidava de facto o império. Disposições: a Trácia Oriental e a região de İzmir para a Grécia; na Anatólia Oriental, previram-se uma Arménia independente e um Curdistão autónomo; a Síria foi deixada à França e o Iraque e a Palestina à Inglaterra como mandatos; os Estreitos foram entregues a uma comissão internacional; o exército foi reduzido a 50.700 homens, as capitulações voltaram e as finanças foram postas sob controlo da Entente. A Grande Assembleia Nacional de Ancara NÃO RECONHECEU de todo o tratado e declarou traidores à pátria os seus signatários; o texto não entrou em vigor e, em seu lugar, veio em 1923 Lausana. Esta é a razão de não ter correspondência no mapa — Sèvres nunca foi aplicado juridicamente.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["O Exército Vermelho entrou na cidade de Bucara — o último emir Âlim Han foi afastado do trono", "f8f5bfcf"], "d": ["O Exército Vermelho entrou na cidade de Bucara a 2 de setembro de 1920 e o último emir mangıt, Âlim Han, foi afastado do trono. O emir recuou para o leste do país, para Düşenbe, e de lá dirigiu durante meio ano a luta contra os soviéticos; o Exército Vermelho tomou Düşenbe a 21 de fevereiro de 1921 e o emir passou mais para leste e dali para o Afeganistão. O canato foi oficialmente abolido a 6 de outubro de 1920 (ver República Popular Soviética de Bucara).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Foi proclamada a República Popular Soviética de Bucara", "ef579627"], "d": ["Depois de o Exército Vermelho, a 28-31 de agosto de 1920, ter derrubado o Emirado de Bucara e feito fugir o emir Alim Han para a Bucara Oriental, foi proclamada a República Popular Soviética de Bucara, presidida por Feyzullah Hocayev.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["A República Popular de Tannu Tuva proclamou a sua independência", "8710ea3d"], "d": ["A independência foi proclamada sob a liderança do Partido Revolucionário Popular de Tuva; o primeiro artigo da primeira constituição estipulava que o Estado atuava 'nas relações internacionais sob a proteção da Rússia Soviética'.", "3c6cec2c"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Foi aprovada a nova constituição da República Popular Soviética de Bucara", "fb17bf39"], "d": ["Foi aprovada uma nova constituição que, ao contrário da constituição russa de 1918, permitia a propriedade privada da terra e da produção e concedia também o direito de voto aos não proletários (com exceção dos parentes do emir deposto e dos grandes proprietários).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["A transformação em República Socialista Soviética de Khwarazm", "14a1d26f"], "d": ["O país, mudando de nome e de estatuto, tornou-se a República Socialista Soviética de Khwarazm; a estrutura administrativo-legal foi reorganizada segundo o sistema soviético.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["O governo de Tannu Tuva entrou de facto em funções", "22ea1516"], "d": ["O governo formado depois da primeira reunião do partido, em fevereiro de 1922, entrou de facto em funções.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["Reuniu-se o primeiro Grande Khural de Tannu Tuva", "80fe15f2"], "d": ["Reuniu-se o primeiro Grande Khural (Assembleia Popular) do país; é a primeira grande reunião representativa no processo de institucionalização do Estado.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["O fim da RSS de Khwarazm e da República Popular Soviética de Bucara com a delimitação nacional — a fundação das RSS do Usbequistão e do Turcomenistão", "e8c8ab4f"], "d": ["Pela decisão soviética de 'delimitação nacional' (natsionalno-territorialnoe razmezhevanie), a República Socialista Soviética de Khwarazm e a República Popular Soviética de Bucara foram abolidas; os seus territórios foram repartidos entre as recém-criadas Repúblicas Socialistas Soviéticas do Usbequistão e do Turcomenistão (o leste de Khiva para o Usbequistão, o oeste para o Turcomenistão). O artigo `harizm` da TDV: 'Em 1924, as partes orientais do Canato de Khiva foram deixadas à República Socialista Soviética do Usbequistão e a parte ocidental à República Socialista Soviética do Turcomenistão.' — dá apenas o ano.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["A venda de Alanya ao sultão mameluco Barsbay", "c8bd35f2"], "d": ["Alanya, tomada em 1293 por Karamanoğlu Mecdüddin Mahmud Bey, tornara-se um beylik separado, governado por um ramo dos Karamanoğulları; Ibn Battuta regista em 1333 que a administração estava com Karamanoğlu Yûsuf Bey. Karaman b. Savcı Bey vendeu em 1427 a cidade ao sultão mameluco Barsbay por cinco mil moedas de ouro e Alanya entrou na administração mameluca. Este porto-chave do Mediterrâneo tornou-se assim um obstáculo, em mãos mamelucas, no caminho dos otomanos para o sul; em 1471, quando Gedik Ahmed Paxá a cercou, o último bei, Kılıcarslan, entregou a cidade.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["A tomada de Tabarka aos genoveses — o fim da concessão do coral dos Lomellini", "b1f33eb5"], "d": ["Depois do tratado que Carlos V fez em 1544 com o bei de Tunes, a família genovesa Lomellini fixara-se na ilha de Tabarka e durante duzentos anos detivera a concessão do coral; a ilha permanecera, no meio da Tunísia otomana, como um posto comercial cristão. Ali Paxá, da dinastia Husseinita, ao saber da tentativa da família de se desfazer da ilha, enviou forças e tomou a ilha a 12 de junho de 1741; cerca de mil e quinhentos cristãos foram transferidos para Tunes. Tabarka passou, a partir desta data, para a administração da milícia (ocaklık) de Tunes.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["A Batalha das Pirâmides e a tomada do Cairo pelos franceses", "3ddd6b96"], "d": ["Napoleão marchou de Alexandria para sul ao longo do Nilo e, a 21 de julho de 1798, enfrentou em Embabeh, em frente a Gizé, a cavalaria mameluca de Murad Bey. A infantaria francesa, em formação quadrada, quebrou as cargas de cavalaria; o exército mameluco dispersou-se e o Cairo rendeu-se dois dias depois sem resistência. Murad Bey recuou para o Alto Egito e İbrâhim Bey para a Síria. Os franceses estabeleceram no Cairo um dîvân e procuraram conduzir a administração por meio dos ulemás; em outubro de 1798 e em março de 1800 rebentaram duas grandes revoltas no Cairo.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["O cerco de Acre por Napoleão — a paragem da campanha da Síria", "d2a947ad"], "d": ["Napoleão, que queria dispersar as forças que os otomanos preparavam para retomar o Egito, marchou para a Síria no início de 1799; tomou Arish a 18 de fevereiro e Jafa em março e, a 18 de março de 1799, cercou Acre. A defesa de Cezzâr Ahmed Paxá e o apoio, por mar, do almirante inglês Sidney Smith quebraram o cerco durante dois meses; como a artilharia de cerco foi capturada no mar, as muralhas não puderam ser transpostas. Napoleão retirou-se em maio e esta derrota foi o ponto extremo da ocupação francesa.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["A fundação do Estado do emir Abdelkader — a centralização da resistência no oeste da Argélia", "9e482383"], "d": ["A resistência, que se dissolvera depois da queda de Argel, reuniu-se à volta do jovem Abdelkader, filho do xeique Kādirî Muhyiddin; a 22 de novembro de 1832, perto de Mascara, os chefes tribais prestaram-lhe fidelidade com o título de 'emîrü'l-mü'minîn'. A estrutura que fundou não era uma aliança tribal, mas um Estado regular: tinha casa da moeda, oficina de pólvora, ordem fiscal e uma capital em Tagdempt. A França reconheceu oficialmente o seu domínio pelo Tratado de Tafna de 1837. Abdelkader refugiou-se não nos otomanos, mas na suserania do sultão de Marrocos Abderramão; ou seja, estas terras, depois de 1832, não são sujeitas otomanas. Rendeu-se a 23 de dezembro de 1847 e o Estado Otomano declarou no mesmo ano que os seus direitos sobre a Argélia tinham terminado.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["A queda de Constantina — o fim do beylik da Argélia oriental", "159fed36"], "d": ["Depois da queda de Argel em 1830, o beylerbeylik oriental não se dissolveu: o último bei, Ahmed, continuou em Constantina o seu próprio governo e declarou agir em nome dos otomanos. A primeira expedição dos franceses, em 1836, terminou em desastre; a segunda cercou a cidade a 6 de outubro de 1837, o comandante Damrémont morreu a 12 de outubro com fogo de canhão e a 13 de outubro as muralhas foram transpostas e a cidade foi tomada rua a rua. Ahmed Bey retirou-se para as montanhas e só se rendeu em 1848. Esta data é o fim de facto da administração otomano-turca de trezentos anos no leste da Argélia.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["A conquista da região de Taka e a fundação de Kassala", "cc3e0631"], "d": ["O governador do Sudão, Ahmed Paxá Ebû Vidân, ligou em 1840 à administração egípcia a região de Taka, entre os rios Atbara e Gash, e fundou a cidade de Kassala como quartel-general militar. A cidade tornou-se um centro de mudîriyet que controlava a rota de caravanas entre Sennâr e Suakin e a faixa fronteiriça da Abissínia.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["A ocupação francesa de Mascara — a perda da capital de Abdelkader", "bd363c05"], "d": ["Com a chegada de Bugeaud ao governo, em 1841, a estratégia francesa mudou: em vez de se manter na costa, ocupar uma a uma as cidades do interior. As colunas móveis saídas de Orão, Mostaganem e Medea tomaram os centros do Estado regular de Abdelkader; Mascara, verdadeira capital com a sua casa da moeda, a sua oficina de pólvora e os seus celeiros, era a mais importante delas. O emir renunciou depois a estabelecer um centro fixo e transformou o seu exército no acampamento nómada chamado 'smala'.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["A ocupação do vale do Chelif e de Tenes — a fundação de Orléansville", "e1eeeb68"], "d": ["Para poderem perseguir Abdelkader, os franceses fundaram em abril de 1843, no meio do vale do Chelif, uma nova cidade chamada Orléansville; no mesmo ano foi também ocupado o porto costeiro de Tenes. Assim, o corredor interior entre Argel e Orão entrou no controlo francês e a resistência nas montanhas de Dahra ficou cercada. A 16 de maio do mesmo ano, a 'smala' nómada de Abdelkader foi encontrada por acaso e dispersada.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["A fundação do campo fortificado de Sidi Bel Abbès", "fb33ec29"], "d": ["Bugeaud deu a 12 de junho de 1843 ao general Bedeau a ordem de estabelecer em Sidi Bel Abbès um campo fortificado com fossos e muralhas; a construção começou a 18 de junho e, em novembro do mesmo ano, um batalhão da Legião Estrangeira instalou-se aí. O campo tornou-se uma base permanente que controlava a planície interior entre Orão e Tlemcen.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["A passagem de Nédroma e da faixa fronteiriça com Marrocos para o controlo francês", "61d821f3"], "d": ["Depois da retirada de Abdelkader para Marrocos, em 1843, Nédroma e a costa de Trâra, a noroeste de Tlemcen, entraram no controlo francês. A Batalha de Isly, de 14 de agosto de 1844, pôs em debandada o exército marroquino e a fronteira entre os dois países foi traçada pela Convenção de Lalla Maghnia de 18 de março de 1845; Nédroma ficou do lado argelino desta linha.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["A queda de Laghouat — a abertura da porta do Saara", "b161b32c"], "d": ["O general Pélissier cercou Laghouat a 21 de novembro de 1852 com uma força de seis mil homens e a cidade caiu a 4 de dezembro, num sangrento assalto. Laghouat era a cidade-oásis que guardava a passagem entre o Tell e o Saara; a sua queda abriu o avanço francês às rotas de caravanas do deserto e preparou o caminho para que a confederação do Mzab fosse sujeita a imposto no prazo de um ano.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["A anexação da região de Bogos ao Egito", "b2ab83ce"], "d": ["Werner Munzinger Paxá, governador da província 'Sudão Oriental e Costa do Mar Vermelho' que o quediva İsmâil fundara na costa ocidental do mar Vermelho, ligou em 1872 ao Egito a região de Bogos, habitada pelo povo Bilen, e o seu centro, Keren. Foi o avanço mais duradouro do Egito na orla do planalto abissínio e iniciou com a Abissínia uma disputa fronteiriça de doze anos.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["A anexação do Sultanato de Darfur ao Egito — Zübeyr Paxá entrou em El Fasher", "f41268ed"], "d": ["Zübeyr Rahmet Paxá, reforçado pelo comércio de marfim e de escravos, dispersou a 25 de outubro de 1874, em Menevâşî, o exército Fur com as forças que equipara com espingardas Remington; o sultão İbrâhim morreu na batalha. Zübeyr entrou em El Fasher a 2 de novembro sem combate, e o governo da dinastia Keyra, que durava desde 1603, terminou de facto. Darfur foi assim incorporado nas províncias do Sudão do Egito de Cavala; mas a resistência da família Keyra nas montanhas prolongou-se até 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["A anexação dos oásis do Mzab (Ghardaïa)", "9372959f"], "d": ["As cidades ibaditas do Mzab tinham aceitado em 1852 pagar imposto à França, mas conservaram a sua administração interna; trinta anos depois, em 1882, a região foi diretamente incorporada no território francês e Ghardaïa foi ligada à administração militar. Assim, a última faixa autónoma do norte do Saara terminou também juridicamente.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["O bombardeamento de Alexandria e o desembarque inglês", "18d57bf8"], "d": ["Quando o movimento de oficiais liderado por Urâbî Paxá pôs o quediva sob controlo, a Inglaterra interveio, a pretexto da segurança da rota do Suez. A esquadra do almirante Seymour bombardeou as baterias costeiras de Alexandria a 11-12 de julho de 1882; depois do incêndio e do saque ocorridos na cidade, tropas inglesas desembarcaram a 15 de julho. O Estado Otomano não pôde impedir esta operação numa província de que era juridicamente soberano e deixou também sem resposta o convite para participar na intervenção. Dava-se assim o primeiro passo da ocupação que duraria trinta e dois anos.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["A Batalha de Tel el-Kebir — a dispersão do exército de Urâbî", "8e38fecf"], "d": ["Wolseley, desembarcando as suas forças em Ismaília pelo Canal do Suez e fazendo-as marchar pelo deserto, atacou de surpresa, ao amanhecer de 13 de setembro de 1882, as trincheiras egípcias de Tel el-Kebir; a batalha terminou numa hora. Urâbî rendeu-se no dia seguinte e a cavalaria inglesa entrou no Cairo no mesmo dia. A partir desta data, as finanças, o exército e os negócios estrangeiros do Egito passaram de facto ao controlo inglês; a soberania otomana subsistiu juridicamente até 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["A Convenção de La Marsa — a conclusão do protetorado sobre Tunes", "71338640"], "d": ["O Tratado do Bardo (Kasrüssaîd) de 12 de maio de 1881 deixara à França os negócios estrangeiros de Tunes, mas deixara ao bei a administração interna; dois anos depois, a Convenção de La Marsa, assinada a 8 de junho de 1883, pôs também as reformas financeiras e administrativas sob controlo francês e completou o protetorado. O Estado Otomano manteve a pretensão de soberania sobre Tunes e nunca reconheceu a ocupação, mas não pôde dar nenhum contrapasso efetivo. Assim, Tunes, milícia (ocaklık) otomana desde 1574, passou oficialmente ao protetorado francês.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["O desastre de Shaykan — a destruição do exército de Hicks Paxá", "a0e08986"], "d": ["Hicks Paxá, oficial inglês reformado que comandava uma força egípcia de cerca de dez mil homens enviada do Cairo, ao avançar sem água e sem guias no deserto do Cordofão foi cercado a 5 de novembro de 1883 em Shaykan pelas forças do Mahdi, e o exército foi quase totalmente aniquilado. Este desastre quebrou a espinha dorsal da administração egípcia no Sudão: em um mês renderam-se Darfur e Bahr el-Ghazal e todo o Cordofão passou para o Mahdi. O caminho para a queda de Cartum começa aqui.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["A passagem de Darfur para as forças do Mahdi — a rendição de Slatin Paxá", "6d8992d4"], "d": ["O governador-geral de Darfur, Slatin Paxá, desde 1882 lidava com a revolta mahdista da tribo Rizeykāt; julgando que as derrotas dos seus soldados se deviam à sua condição de cristão, fez-se abertamente muçulmano em 1883 e tomou o nome de Abdülkādir. Depois de o exército de Hicks Paxá ter sido destruído no Cordofão em novembro de 1883, a resistência perdeu sentido e a 23 de dezembro de 1883 rendeu-se ao emir Madibbo. Os pequenos postos egípcios em Darfur seguiram em pouco tempo o mesmo caminho; a administração turco-egípcia de dez anos terminou.", "85dcfe97"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["A passagem de Zeila e da costa da Somália para a administração inglesa", "1d649502"], "d": ["Quando a insurreição do Mahdi fez ruir as guarnições egípcias do Sudão e do mar Vermelho, o Cairo foi obrigado a evacuar os seus postos distantes na costa abissínia. A administração inglesa de Áden desembarcou tropas em Zeila e Berbera em 1884; no ano seguinte, assinaram-se tratados de proteção com os chefes tribais somalis e foi fundada a Somalilândia Britânica. Zeila, ligada à província da Abissínia desde 1559, perdeu-se assim.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["A rendição da guarnição de Fasher aos mahdistas", "68f0760d"], "d": ["Mesmo depois da rendição de Slatin a 23 de dezembro de 1883, a guarnição egípcia da fortaleza de Fasher resistiu. A guarnição, que perdera os poços num cerco de sete dias, rendeu-se a 15 de janeiro de 1884; as armas foram depostas e a fortaleza passou para os mahdistas.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["O Tratado de Hewett (Adua) — Bogos foi deixada à Abissínia", "0de1b701"], "d": ["Quando a insurreição do Mahdi cercou as guarnições egípcias no Sudão, a Inglaterra assinou a 3 de junho de 1884, em Adua, um tratado com Yohannes IV, para obter a ajuda da Abissínia. O segundo artigo do tratado devolvia Bogos à Abissínia e, em contrapartida, a Abissínia facilitava a evacuação das guarnições cercadas por Maçuá. Keren saiu assim da administração egípcia de doze anos; cinco anos depois, a região seria incorporada na Eritreia italiana.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["A reconquista de Dongola — o início da campanha ao longo do Nilo", "f63aa14f"], "d": ["Depois da derrota dos italianos em Adua, a Inglaterra fez marchar o exército egípcio para sul, ao longo do Nilo, sob o comando de Kitchener. À medida que a via-férrea avançava pelo deserto, o problema do abastecimento foi resolvido e a província de Dongola foi recuperada a 23 de setembro de 1896. O governo mahdista de onze anos terminou aqui; a campanha prolongar-se-ia por mais dois anos até chegar a Omdurman.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["A Batalha de Omdurman — a queda do Estado Mahdista", "28dff7b2"], "d": ["O exército anglo-egípcio de Kitchener, equipado com artilharia e metralhadoras, dispersou em poucas horas, a 2 de setembro de 1898, diante de Omdurman, as forças do califa Abdullah et-Teâyişî. No dia seguinte entrou-se em Cartum e hasteou-se a bandeira no palácio onde Gordon fora morto treze anos antes. A capital do Estado Mahdista caiu; o califa foi morto, no fim de 1899, numa operação de perseguição. O domínio de facto muda de mãos nesta data — 19 de janeiro de 1899 é o tratado que estabelece o quadro jurídico da administração.", "ae944d9d"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["O Tratado do Condomínio — a administração conjunta anglo-egípcia do Sudão", "8033c688"], "d": ["O tratado assinado no Cairo quatro meses depois de Omdurman pôs o Sudão, sob o nome de 'Sudão Anglo-Egípcio', sob a administração conjunta dos dois Estados: as duas bandeiras seriam hasteadas juntas e o governador-geral seria nomeado pelo quediva com o consentimento da Inglaterra. Na prática, a administração estava inteiramente nas mãos dos ingleses. O Estado Otomano, sustentando que os seus direitos sobre o Sudão lhe pertenciam por intermédio do Egito, não foi parte no tratado e não o reconheceu; mas de facto ficou de fora.", "c642933f"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["O desembarque italiano em Tobruk — a primeira ocupação em Trípoli de Barbaria", "44780018"], "d": ["A Itália declarou guerra a 29 de setembro de 1911 e a sua frota bloqueou a costa a 25-26 de setembro. A primeira operação terrestre foi feita a 8 de outubro em Tobruk: a pequena guarnição otomana recuou para o interior e o porto foi ocupado sem combate. Tobruk era o porto otomano mais próximo da fronteira do Egito; a sua queda abriu o flanco oriental de Barca e facilitou a marcha das forças italianas para oeste ao longo da costa.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["A rendição da cidade de Trípoli aos italianos", "785091ad"], "d": ["Trípoli rendeu-se a 9 de outubro de 1911, depois de três dias de bombardeamento. As forças otomanas, em vez de defender a cidade, preferiram recuar para Aziziye e Garyan e organizar a resistência no interior; esta resistência, em que participaram Enver e Mustafa Kemal Beys, manteve os italianos confinados à faixa costeira até ao fim da guerra. Ou seja, embora a cidade tenha caído, o interior da província permaneceu sob controlo otomano.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["A perda de Derna com o desembarque italiano", "f014c741"], "d": ["Depois de Tobruk, chegou a vez de Derna, segundo porto de Barca; a cidade foi ocupada a 16 de outubro de 1911. O planalto em redor de Derna era a região onde a confraria Senûsiyye era mais densa, e os mujahidin reunidos com o apelo à jihad do xeique Ahmed Şerîf mantiveram os italianos cercados em redor do porto. A ocupação ficou limitada à cidade e nunca se estendeu ao interior.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["O desembarque italiano em Benghazi — a perda do centro do sanjaco de Barca", "f9183c40"], "d": ["Benghazi, centro de Barca, foi ocupada a 21 de outubro de 1911, com o quarto e mais importante desembarque na costa. Assim, três semanas depois da declaração de guerra, a Itália detinha todos os grandes portos da província de Trípoli de Barbaria (Trípoli, Tobruk, Derna, Benghazi); mas não conseguiu penetrar no interior de nenhum deles. O resto do ano de guerra passou-se em investidas infrutíferas destes quatro pontos da costa para o interior.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["O decreto de anexação unilateral da Itália", "cfe3f9c2"], "d": ["A Itália, durante a guerra, promulgou a 5 de novembro de 1911 um decreto declarando que anexava Trípoli de Barbaria e Barca. O Estado Otomano não o reconheceu e a guerra durou mais um ano; a anexação só ganhou validade jurídica com o Tratado de Ouchy de 18 de outubro de 1912. Por isso, o decreto não muda a cor otomana no mapa — a propriedade jurídica está com os otomanos até 1912, e o controlo italiano é mostrado como ocupação tracejada.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Tomada de Köprühisar e preparação da fundação de Yenişehir", "39abff03"], "d": ["Derrubadas as fortalezas de passagem entre Bursa e İznik, lançou-se a base do quartel avançado que sitiaria as duas cidades.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Fundação de Yenişehir", "d3275837"], "d": ["Foi criado o primeiro povoamento-guarnição otomano regular para dirigir os cercos de Bursa e de İznik; Orhan Gazi nasceu aqui.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Primeiro cerco de İznik e conquista de Marmaracık", "cdca2349"], "d": ["İznik foi sitiada pela primeira vez mas não pôde ser tomada (conquista definitiva em 1331); a fortaleza de Marmaracık, nas suas proximidades, foi tomada nesta altura.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Campanha dos contingentes catalães na Anatólia", "4fd940d5"], "d": ["A companhia catalã contratada por Bizâncio para deter o avanço turco obteve êxitos passageiros mas não foi duradoura; com a sua retirada, o avanço dos beyliks de fronteira acelerou.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal torna-se muçulmano e junta-se aos otomanos", "ca0d86e1"], "d": ["Köse Mihal, tekfur de Harmankaya, converteu-se ao Islão e juntou-se a Osman Gazi com a sua fortaleza e os seus homens; tornou-se o primeiro comandante otomano de origem bizantina.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey assume de facto a administração", "6dadbefc"], "d": ["Devido à velhice e à doença de Osman Gazi, a direção e administração de facto do cerco de Bursa e das campanhas passou para o seu filho Orhan Bey (a subida oficial ao trono é em 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-01-01:0":{"b": ["Bloqueio do porto de Mudanya", "9aa4520c"], "d": ["Cortado o porto que abastecia Bursa pelo mar, abriu-se o último ato do longo cerco.", "97d6f814"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Tomada de Mudanya", "0a623368"], "d": ["Com a tomada de Mudanya, porto de Bursa, a ligação da cidade ao mar foi cortada; o cerco de Bursa entrou na fase de estrangulamento.", "c13020d5"]},
"OLAYLAR_EK:1323-01-01:0":{"b": ["Incorporação de Yalova e Karamürsel", "133cb07a"], "d": ["Para completar o cerco de Bursa, foram tomadas as vilas portuárias da costa sul do golfo.", "6588050d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Conquista de Akyazı e da Ilha de İmralı", "d041b0c8"], "d": ["Foi tomada Akyazı, a norte do Sakarya; com a captura da Ilha de İmralı, os otomanos tornaram-se pela primeira vez vizinhos da Ilha de Mármara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Conquista de Gemlik (Kios) e Armutlu", "682d3bac"], "d": ["Cortada também a última ligação marítima de Bursa, a cidade ficou preparada para a rendição de 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca tomou Kandıra e arredores", "341bb97e"], "d": ["Akça Koca, um dos beys de fronteira de Orhan Gazi, enquanto fazia incursões à região de İzmit a partir do seu quartel a oeste do lago Sapanca, apoderou-se por volta de 1326 de Kandıra e dos seus arredores. İzmit estava ainda em mãos bizantinas; a cidade só cairia em 1337.", "ed042ad1"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca tomou Aydos e a fortaleza de Samandıra", "ce4daa8a"], "d": ["Após a tomada de Kandıra, Akça Koca, juntamente com Konuralp e Gazi Abdurrahman, tomou a fortaleza de Aydos, nas imediações de Kartal, e depois a fortaleza de Samandıra, a norte dela; a região de Samandıra foi-lhe dada como propriedade. Akça Koca morreu em 1328 perto de Kandıra; o beylik de fronteira da região foi dado ao príncipe Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Aliança otomano-Aydın-Saruhan", "9df6bb74"], "d": ["Os três beyliks agiram em conjunto contra Bizâncio; a armada do Aydınoğlu Umur Bey desgastou Bizâncio numa segunda frente com incursões às costas da Trácia.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Casamento de Orhan Gazi com Teodora: aliança bizantina", "9b67a590"], "d": ["Orhan Gazi, que apoiava Cantacuzeno na luta pelo trono bizantino, casou com a filha dele, Teodora; esta aliança permitiu às forças otomanas conhecer de perto a Rumélia.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Tomada de Ancara", "49bf1f6d"], "d": ["Ancara, sob administração ahi, passou à administração otomana; abriu-se o caminho da Anatólia central. Outros lugares incorporados na mesma data: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Avanço na Trácia no tempo de Süleyman Paşa: Malkara, İpsala e Tekirdağ", "fb31cf02"], "d": ["Depois de estabelecida a cabeça de ponte em Galípoli, Süleyman Paşa, subindo da península para norte, tomou passo a passo a planície entre a costa do Mármara e a foz do Maritsa. Malkara, İpsala e Rodosçuk (Tekirdağ) formaram assim um corredor ininterrupto ligando Galípoli ao vale do Maritsa. Sem este corredor não se podia marchar sobre Edirne; o avanço, detido pela morte súbita do príncipe em 1357, seria prosseguido por Lala Şahin e Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Rapto do príncipe Halil", "b52ac3d7"], "d": ["Halil, filho mais novo de Orhan Gazi, foi raptado por piratas de Foça; a crise do resgate ocupou durante anos as relações otomano-bizantinas.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Corte das vias de socorro de Edirne: fortalezas de Çorlu, Lüleburgaz, Babaeski e Keşan", "8e8ad485"], "d": ["O príncipe Murad, que retomou as operações de conquista depois do salvamento de Halil, enviou os akıncıs até diante de Constantinopla para isolar Edirne de qualquer auxílio exterior. Foram tomadas as fortalezas de Çorlu, Lüleburgaz e Babaeski, na estrada Constantinopla-Edirne, e Keşan, no entroncamento rodoviário da Trácia meridional. A rendição de Edirne veio depois de completado este anel de cerco.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Tomada de Dimetoka — abertura do vale do Maritsa", "b59aee83"], "d": ["Foi tomada Dimetoka, fortaleza-chave do vale do Maritsa; abriu-se assim o caminho da conquista de Edirne. Sem estar completo o corredor que se estende de Galípoli para norte, não era possível marchar sobre Edirne, e por isso a fortaleza vem, na ordem das conquistas da Rumélia, antes de Edirne. A cidade foi durante algum tempo o quartel-general dos sultões na Rumélia. As forças que tomaram Dimetoka puseram em seguida sob controlo toda a região do Maritsa médio, juntamente com pequenas fortalezas como Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Perda de Galípoli (cruzada de Saboia)", "00e7e415"], "d": ["A armada de Amadeu de Saboia, primo do imperador bizantino, tomou Galípoli e entregou-a a Bizâncio; a cabeça de ponte otomana na Rumélia foi durante dez anos governada a partir da outra margem do estreito. Outros povoamentos perdidos na mesma data: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Batalha de Çirmen — controlo do vale do Maritsa", "cd738d8d"], "d": ["O exército dos beys sérvios foi dispersado num ataque noturno; os beys locais sérvios/búlgaros da Macedónia e dos Ródope começaram, um a um, a pagar tributo aos otomanos — não uma conquista direta, mas o início de uma vaga de vassalização. Na tradição otomana, esta batalha é ainda narrada com o nome de «Sırpsındığı» e com a data de 1364, como o ataque noturno de Hacı İlbey ao exército cruzado que vinha reconquistar Edirne; o TDV indica que essa data é errada e que as duas narrativas pertencem à mesma batalha.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Conquista de Filibe e Eski Zağra", "e780c9ae"], "d": ["Foram tomadas Filibe, a montante do vale do Maritsa, e Eski Zağra, a norte; o czarado búlgaro foi sujeito a tributo. A rota de Tatarpazarcığı e İhtiman, entre Filibe e Sófia, ficou nas mãos dos beys locais vassalizados depois de Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bizâncio vassalo: João V no exército de Murad I (consequência da vitória de Çirmen de 1371)", "13ffe568"], "d": ["Segundo o TDV, depois da vitória de Çirmen (Maritsa) de 26 de setembro de 1371, o Império Bizantino reconhecera a soberania otomana e caíra na condição de Estado vassalo, aceitando pagar tributo e servir no exército otomano. O imperador João V, com esta obrigação, juntou-se em 1373 ao exército de Murad I; o seu filho André IV, que deixara então em Constantinopla, revoltou-se contra o pai juntamente com o príncipe Savcı Bey, em Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Recuperação de Galípoli", "5f96c0a5"], "d": ["André IV, que obtivera o apoio otomano na luta pelo trono bizantino, restituiu Galípoli em troca; a ponte entre a Rumélia e a Anatólia foi restabelecida. Outros lugares incorporados na mesma data: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Dote de Germiyan: incorporação de Kütahya", "d6a6fe61"], "d": ["No casamento de Devletşah Hatun, filha do Germiyanoğlu Süleyman Şah, com Yıldırım Bayezid, Kütahya, Simav, Tavşanlı e Eğrigöz passaram aos otomanos como dote — exemplo clássico de expansão sem guerra. Outros lugares incorporados na mesma data: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Compra da província de Hamîd: incorporação de Isparta", "4a1b6047"], "d": ["O Hamîdoğlu Hüseyin Bey vendeu a Murad I, a dinheiro, uma parte do seu beylik (Akşehir-Beyşehir-Isparta); o resto da província de Hamîd seria anexado por Yıldırım em 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Conquista de Serez", "d4d28b60"], "d": ["Foi tomada Serez, chave da Macedónia oriental; Salónica entrou no círculo de cerco. A linha Köstendil-Petriç-Nevrokop-Drama, entre Sófia e Serez, não estava ainda diretamente incorporada nesta data; passou sucessivamente a vassala entre os anos 1370 e 1383 e a administração direta depois de 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Conquista de Sófia", "96d5f01f"], "d": ["Foram postas sob controlo as passagens ocidentais dos Balcãs; como nesta data Serez estava já em poder desde 1383, os territórios da Trácia e da Macedónia formavam um conjunto ininterrupto.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Conquista de Niš", "77f5d632"], "d": ["Com a tomada de Niš, chave do vale do Morava, o despotado sérvio ficou diretamente ameaçado.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Primeira rendição de Salónica", "96010ee9"], "d": ["Após um longo bloqueio, a cidade rendeu-se (será devolvida a Bizâncio em 1403 e conquistada definitivamente em 1430). Outros lugares incorporados na mesma data: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidnâme otomano-genovês — renovação do tratado de 1352", "be11d17a"], "d": ["Com os enviados genoveses vindos de Pera, foi renovado o acordo comercial de 1352 herdado do tempo de Orhan Gazi; foram de novo fixados os impostos entre os dois Estados, o tratamento dos prisioneiros e o comércio livre. Este é considerado o primeiro ahidnâme oficialmente conhecido de amizade e comércio entre os otomanos e os genoveses — não uma aliança militar, mas um acordo inteiramente comercial.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Campanha de Çandarlı Ali Paşa na Bulgária: tomada de Şumnu e Rusçuk", "2781c3a9"], "d": ["As fortalezas do czarado búlgaro ao longo do Danúbio foram recebidas em rendição numa única campanha; não deve ser confundida com a derrota sofrida no mesmo ano em Bileća, na Bósnia — foi um êxito simultâneo numa frente distinta. Tırnova e Vidin eram ainda os últimos centros búlgaros mantidos.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Derrota de Bileća", "89ba0a64"], "d": ["A força de akıncıs que se dirigia à Bósnia foi apanhada numa emboscada em Bileća e aniquilada; este primeiro grande revés balcânico encorajou a aliança que conduziu ao Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Anexação dos beyliks da Anatólia ocidental: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Três beyliks foram incorporados de uma só vez: Manisa, centro dos Saruhanoğulları; Aydın, centro dos Aydınoğulları (incluindo a cidadela superior de Esmirna, mas o porto/cidadela inferior ainda com os Cavaleiros de São João — até 1402); Muğla-Milas, centro dos Menteşeoğulları, incluindo a faixa costeira Datça-Bodrum-Marmaris-Fethiye. As costas do Egeu foram pela primeira vez reunidas numa só mão. Outros lugares incorporados na mesma data: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1391-10-01:0":{"b": ["Começou o primeiro bloqueio de Constantinopla", "4441a9e7"], "d": ["Yıldırım Bayezid manteve Constantinopla sob bloqueio intermitente durante dez anos; a cidade só se salvou graças à aproximação de Tamerlão.", "504fcb33"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Anexação da província de Teke: incorporação de Antalya", "fdbeee5c"], "d": ["A província de Teke, na costa mediterrânica, foi incorporada no território otomano. Os Tekeoğulları são um ramo separado dos Hamîdoğulları: Feleküddin Dündar Bey deixou Antalya, que conquistara, ao seu irmão Yûnus Bey, e por volta de 1321 nascera um beylik distinto. Por isso, Antalya e os seus arredores são mostrados no mapa depois de 1321 com a cor dos Tekeoğulları e não dos Hamîdoğulları. O beylik foi refundado depois da batalha de Ancara e só foi liquidado definitivamente em 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Conquista de Üsküp", "9e5a1af5"], "d": ["Foi tomado o centro da Macedónia do Vardar; Üsküp tornou-se um dos principais centros de fronteira da Rumélia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Anexação de Kastamonu", "876330ba"], "d": ["O ramo de Kastamonu dos Candaroğulları foi liquidado; o ramo de Sinope continuou como vassalo. Outros lugares incorporados na mesma data: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Queda de Tırnova — anexação da Bulgária", "ff666977"], "d": ["A capital do czarado búlgaro caiu; a Bulgária passou à administração otomana direta. Outros lugares incorporados na mesma data: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["A fortaleza de Lofça (Lovech) passa aos otomanos", "a55e87a0"], "d": ["Lofça, uma das fortalezas do czar búlgaro Ivan Šišman, foi incorporada no território otomano com as outras províncias de Šišman na campanha de 1393 em que Tırnova caiu. A fonte não é categórica: «supõe-se» que a conquista foi neste ano.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Incorporação da Dobruja", "478e36f2"], "d": ["Foram incorporados os territórios da Dobruja, que se estendem até ao delta do Danúbio. Outros lugares incorporados na mesma data: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Descida à Tessália", "8bec60dd"], "d": ["A planície da Tessália, com centro em Yenişehir (Larissa), foi posta sob administração otomana. Outros lugares incorporados na mesma data: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Conquista de Niğbolu", "b9791717"], "d": ["Após a batalha de Rovine de 1395 contra os valáquios, Yıldırım Bayezid tomou a fortaleza de Niğbolu, nas margens do Danúbio; algumas crónicas búlgaras anónimas indicam que a conquista se deu em 3 de junho de 1395. A data da conquista não é única nas fontes: o artigo Niğbolu Savaşı da TDV İslâm Ansiklopedisi escreve que Bayezid tomou Silistre e Niğbolu numa campanha do Danúbio em 1394. A fortaleza seria sitiada na célebre Cruzada de 1396, mas não cairia. Outros lugares incorporados na mesma data: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1395-05-17:0":{"b": ["Batalha de Rovine — campanha da Valáquia", "343ae7a9"], "d": ["Após a batalha sangrenta e de resultado discutido com o voivoda da Valáquia, Mircea, a Valáquia aceitou pagar tributo aos otomanos; estabeleceu-se a ordem de vassalagem a norte do Danúbio.", "dd69200f"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Construção de Anadolu Hisarı", "aa259b00"], "d": ["Para apoiar o bloqueio de Constantinopla, foi construída na margem anatólica do Bósforo a Güzelcehisar (Anadolu Hisarı) — o primeiro passo duradouro do controlo do estreito.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Anexação de Vidin", "ee1ae44b"], "d": ["Após a vitória de Niğbolu, foi também anexado Vidin, o último principado búlgaro.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Primeira anexação de Karaman", "3cf07876"], "d": ["Com a vitória de Akçay, o território dos Karamanoğlu foi pela primeira vez incorporado nos otomanos (será refundado durante o Fetret).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Incorporação das costas de Canik: Samsun", "af9c40fa"], "d": ["No vazio criado pela captura de Kadı Burhâneddin pelo Ak Koyunlu Karayülük Osman Bey, Yıldırım Bayezid pôs primeiro sob administração otomana a região de Canik, na costa do mar Negro. Samsun e os seus arredores tornaram-se assim o primeiro porto do mar Negro da dinastia. A linha interior Sivas-Tokat-Kayseri seria incorporada duas semanas depois, com a dissolução de facto do Estado de Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Tomada de Malatya", "7cb6ae16"], "d": ["Foi tomada Malatya, na fronteira mameluca — um dos passos que aumentaram a tensão com Tamerlão.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Tamerlão tomou Malatya e entregou-a a Karayülük Osman — quando Tamerlão se retirou, os Dulkadıroğulları recuperaram-na", "ad2ce7d8"], "d": ["Yıldırım Bayezid tinha regressado a Bursa, deixando Malatya, que tomara em 1399, ao Dulkadıroğlu Nasreddin Mehmed. Tamerlão, que entrou na Anatólia em 1400, tomou primeiro Sivas e Elbistan e depois Malatya; a cidade e os seus arredores foram saqueados e a sua administração foi entregue a Karayülük Osman, que estava ao lado de Tamerlão. Quando Tamerlão deixou a região, os Dulkadıroğulları voltaram a dominar Malatya; o domínio otomano terminou assim antes de Ancara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Tratado de Süleyman Çelebi com Bizâncio: restituição de Salónica", "cc503cc2"], "d": ["Süleyman Çelebi, que dominava a Rumélia durante o Fetret, chegando a acordo com Bizâncio e os Estados latinos, abandonou a Bizâncio Salónica e as costas do mar Negro até Misivri (TDV fetret-devri: Tratado de Galípoli, fevereiro de 1403) — no mapa, İğneada, Rezve e Ahtapolu passam a Bizâncio; no mapa, Salónica sai dos otomanos nesta data.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Derrota naval de Galípoli (Veneza)", "b71d4d68"], "d": ["A armada veneziana infligiu uma pesada derrota à armada otomana diante de Galípoli; foi um acontecimento que mostrou os limites da marinha otomana primitiva.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Revolta do Falso Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, que afirmava ser filho de Yıldırım, proclamou-se sultão na Rumélia com apoio bizantino; Murad II reprimiu a revolta em 1422 e mandou executar o rival.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Cerco de Constantinopla por Murad II", "4b9d9fba"], "d": ["Em resposta ao apoio de Bizâncio ao Falso Mustafa, Murad II sitiou Constantinopla; o cerco foi levantado quando o seu irmão Küçük Mustafa foi sublevado na Anatólia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Cedência de Salónica a Veneza", "bfa6c4a0"], "d": ["O governador bizantino, sob pressão otomana, cedeu a cidade a Veneza; começou a disputa otomano-veneziana que duraria sete anos.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Nova anexação dos beyliks da Anatólia ocidental: Menteşe e Aydın", "aca30a48"], "d": ["Os dois beyliks do Egeu, refundados durante o Fetret Devri, foram definitivamente incorporados no território otomano no tempo de Murad II. Segundo o artigo Menteşeoğulları do TDV, Murad II tomou a província de Menteşe em 827 (1424) e mandou prender os dois irmãos que estavam à frente do beylik. Segundo o artigo Aydınoğulları, o beylerbei da Anatólia Hamza Bey mandou capturar Cüneyd Bey, que de novo se recusara a obedecer, e executou-o com a sua família (829/1425-26), e a província de Aydın passou aos otomanos. Os Cavaleiros de São João, que detinham desde 1344 a cidadela portuária de Esmirna, tinham-na perdido para Tamerlão em 1402, e a região voltara ao controlo dos Aydınoğlu; com esta anexação, ela foi também incorporada nos otomanos. A província de Teke (Antalya) não é objeto deste artigo: os Tekeoğulları tinham sido liquidados à parte em 1423. Germiyan seria incorporada por testamento em 1429.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Anexação de Germiyan por testamento", "9eb86b77"], "d": ["O bey de Germiyan, Yakub II, que morreu sem filhos, legou o seu país por testamento aos otomanos — o exemplo de anexação sem guerra que entrou nos manuais. Outros lugares incorporados na mesma data: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Conquista definitiva de Salónica", "bc021768"], "d": ["A cidade, sob administração veneziana, foi tomada de assalto; o segundo grande porto da Rumélia tornou-se definitivamente otomano. Outros lugares incorporados na mesma data: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Rendição de Ioannina", "ee45cb52"], "d": ["Ioannina, centro do Épiro, rendeu-se por tratado.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Primeira tomada de Semendire", "c11ca17d"], "d": ["Com um cerco de três meses foi tomada a capital do despotado sérvio e a Sérvia foi anexada pela primeira vez (será restituída com o Tratado de Edirne-Szeged de 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Cerco de Belgrado (malogrado)", "3e05f425"], "d": ["O primeiro grande cerco de Belgrado, de seis meses, não deu resultado; a fortaleza permaneceu durante oitenta anos como fecho do avanço otomano.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Desastre de Zlatica — 'Longa Campanha'", "97df1466"], "d": ["O exército que Hunyadi fez entrar nos Balcãs em pleno inverno passou Niš e Sófia e chegou a Zlatica; a defesa otomana resistiu com dificuldade. Este ar de derrota trouxe à mesa a paz de Edirne-Szeged.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Tratado de Edirne-Szeged", "0aa4e0de"], "d": ["Paz de dez anos: o despotado sérvio foi restituído, o Danúbio foi aceite como fronteira. A rutura do tratado, em poucos meses, por instigação papal, conduziu ao desastre de Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Restituição de Semendire e das fortalezas sérvias à Sérvia", "cda3cf9e"], "d": ["A disposição do Tratado de Edirne-Szeged foi posta em execução: Murad II devolveu a Đurađ Branković, em 15 de agosto de 1444, Semendire com as suas vinte e quatro fortalezas importantes e os outros territórios sérvios ocupados (TDV semendire); também Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) e Priština (TDV pristine) foram deixadas aos sérvios. Vidin não entrou na restituição por não ser território sérvio — é essa a origem da perda territorial a noroeste que se vê no mapa por volta da vitória de Varna; poucos meses depois, com o desastre de Varna, o tratado ficará de qualquer modo inválido.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Concluída Rumeli Hisarı — 'Boğazkesen'", "480e8a76"], "d": ["Com a fortaleza concluída, segundo as fontes, numa construção extraordinariamente rápida de quatro a cinco meses, o controlo do Bósforo passou inteiramente aos otomanos; fechou-se o caminho de socorro do mar Negro a Constantinopla. É considerado o primeiro passo efetivo do cerco.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Começou o cerco de Constantinopla", "8af50742"], "d": ["O exército instalou-se diante das muralhas; no cerco, que duraria 54 dias, os canhões gigantescos foram pela primeira vez usados de forma sistemática contra as muralhas de uma capital.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Navios descidos por terra ao Corno de Ouro", "4f2ba07c"], "d": ["Cerca de 70 navios da armada, que não podia entrar no Corno de Ouro fechado por uma corrente, foram arrastados sobre calhas untadas pelas colinas de Gálata e descidos numa noite ao Corno de Ouro; a defesa ficou dividida em duas frentes.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Conquista de Atenas", "4f0f1bb2"], "d": ["O Ducado de Atenas chegou ao fim; o estandarte otomano foi hasteado na Acrópole. Outros lugares incorporados na mesma data: İstefe (Tebas), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Anexação da Sérvia (queda de Smederevo)", "75fd0a62"], "d": ["Smederevo, capital do despotado sérvio, rendeu-se; a Sérvia tornou-se um sanjaco otomano.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Conquista da Moreia", "7d5a3c18"], "d": ["O despotado da Moreia foi liquidado; a península (exceto as fortalezas venezianas) passou à administração otomana.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Incorporação de Sinope", "e03c2739"], "d": ["O Candaroğlu entregou Sinope sem combate; abriu-se o caminho da campanha de Trebizonda. Outros lugares incorporados na mesma data: Kastamonu, Bartın, Safranbolu.", "4fa22834"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Destruição do Reino da Bósnia — campanha da Bósnia do Conquistador", "5362e3f2"], "d": ["Quando o último rei bósnio, Stjepan Tomašević (1461-1463), confiando no apoio ocidental, recusou pagar o tributo, foi considerado como tendo deixado de ser soberano vassalo, e o exército sob a direção do sultão Maomé II, o Conquistador, liquidou o Reino da Bósnia numa só campanha. O rei foi capturado e executado, o reino desapareceu e na região foi criado o sanjaco da Bósnia. Porém, a destruição do reino não é a mesma coisa que a conquista da Bósnia. A administração otomana existia na planície há já quinze anos — Hodidjed e a planície de Saray tinham sido tomadas em 1448, e o beylik de fronteira de Îsâ Bey fora estabelecido no meio do reino. A conquista não acabou também em 1463: Foča em 1465, Livno em 1469, o Ducado da Herzegovina em 1483, o banado de Srebrenik em 1512, e Jajce e Banja Luka, no norte, só puderam ser tomadas em 1528, depois de Mohács — os húngaros tinham constituído, depois de 1463, um banado que se manteve sessenta e cinco anos no norte da Bósnia. O lugar que mudou diretamente de mãos nesta data é Travnik; Jajce, por seu lado, passou nesta data não aos otomanos, mas à Hungria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Anexação definitiva de Karaman", "f1dcecaa"], "d": ["Os territórios centrais dos Karamanoğulları foram definitivamente incorporados; as disputas internas prolongaram-se até aos anos 1470. Outros lugares incorporados na mesma data: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Conquista de Negroponte", "5c97daf3"], "d": ["Caiu Negroponte, principal base de Veneza no Egeu.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Anexação de Alanya, Anamur e Silifke (İçel)", "a0b9d461"], "d": ["A faixa costeira de İçel, ligada aos Karamanoğulları (todo o Mediterrâneo entre Antalya e Mersin), foi incorporada pela campanha naval de Gedik Ahmed Paşa; Alanya era importante pelo seu estaleiro estratégico herdado do período seljúcida.", "8302df58"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Tratado de Istambul — Albânia e Shkodër", "b09652f7"], "d": ["Terminou a guerra otomano-veneziana de 16 anos; Shkodër e as costas da Albânia ficaram com os otomanos. Outros lugares incorporados na mesma data: Limni, Sisam, Bozbaba (Ay Strati).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Desembarque em Otranto", "7916b89d"], "d": ["As forças otomanas que desembarcaram na costa da Calábria sitiaram e tomaram a fortaleza de Otranto; como a cidade foi tomada de assalto, parte dos notáveis que resistiram foi executada e parte foi feita prisioneira. A tradição da Igreja recorda os mortos como os cerca de 800 'mártires de Otranto'; o TDV atribui o exagero deste número à propaganda eclesiástica. Apenas a fortaleza na ponta da península de Salento e a sua estreita vizinhança foram mantidas; o resto do território do Reino de Nápoles na linha Taranto-Brindisi-Lecce não se perdeu — esta cabeça de ponte aberta para a Itália duraria um ano.", "f60d286a"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evacuação de Otranto", "37371bb0"], "d": ["Com a morte de Maomé II, o Conquistador (3 de maio de 1481), a guarnição de Otranto, sem esperança de novos reforços, evacuou a fortaleza por acordo perante o cerco do herdeiro de Nápoles, Afonso; a única cabeça de ponte otomana na Itália perdeu-se assim um ano depois.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Conquista de Modon e Koron", "38b608c4"], "d": ["Foram tomados Modon e Koron, os 'dois olhos' de Veneza na Moreia.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Conquista de Durrës", "1f231b98"], "d": ["Durante a guerra otomano-veneziana de 1499-1503, as forças sob o comando de Mehmed Bey tomaram Durrës, o último grande porto albanês de Veneza no Adriático. Depois de Shkodër (1479) e de Vlorë (1417), com esta conquista a faixa costeira da Albânia passou inteiramente ao controlo otomano.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Incorporação da Anatólia oriental", "e0cb8f8f"], "d": ["Depois de Çaldıran, Diyarbakır e os seus arredores foram incorporados; os beyliks curdos foram ligados aos otomanos por intermédio de İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Conquista da fortaleza de Varadin (Petrovaradin)", "abf392a5"], "d": ["O exército que partira para a campanha de Mohács passou de Belgrado para o território húngaro; foram tomados primeiro os arrabaldes de Varadin e, após um cerco de catorze dias, caiu também a fortaleza. O Legislador ordenou que as aldeias do caminho não fossem queimadas, porque estas eram já consideradas território otomano.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Rendição de Buda depois de Mohács — dois reis para o trono húngaro", "9d3568a0"], "d": ["As chaves da cidade foram apresentadas ao sultão em 11 de setembro de 1526 ao exército otomano que, depois da vitória de Mohács, marchava sobre Buda; contudo, o Legislador não manteve Buda e retirou o seu exército. Na Hungria, que ficou sem rei, os nobres elegeram dois reis distintos: János Szapolyai em 10 de novembro de 1526 e o Habsburgo Fernando I em 17 de dezembro de 1526. Fernando tomou Buda em agosto de 1527. A instalação de Szapolyai em Buda como rei sob a proteção otomana far-se-á com a campanha de 1529 (ver o item de 1529), e a administração otomana direta será estabelecida em 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai eleito rei da Hungria — os otomanos reconheceram o seu reino sob condição de vassalagem", "32bc6baf"], "d": ["Para o trono húngaro, vago pela morte do rei em Mohács, uma parte da nobreza elegeu o voivoda da Transilvânia, János Szapolyai; Szapolyai foi coroado em Székesfehérvár. Os otomanos, que tinham evacuado Buda, reconheceram o reino de Szapolyai sob condição de que lhes fosse vassalo, para manter a região como zona-tampão. No mapa, os lugares ligados a Szapolyai aparecem, a partir desta data, como vassalos dos otomanos.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Fernando I proclamado rei da Hungria — Hungria ocidental e setentrional para a coroa dos Habsburgos", "b3910a2f"], "d": ["O arquiduque habsburgo Fernando, com base no casamento da sua irmã com Luís II, reivindicou o trono húngaro e foi proclamado rei por uma parte dos nobres. A Hungria ficou assim dividida entre dois reis; as suas partes ocidental e setentrional reconheceram Fernando. Os nobres croatas elegeram-no também no início de 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Disputa dos dois reis: Esztergom sob a proteção dos Habsburgos, Szeged com Szapolyai", "da92dee5"], "d": ["Esztergom, que mudara de mãos entre os dois reis desde 1526, passou à proteção dos Habsburgos depois de o arcebispo ter seguido para o norte com o arquivo e o tesouro. Desde o mesmo ano e até 1541, Szeged ficou sob a soberania de Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["A população de Pécs passou para o lado de Szapolyai", "3fc4e7f2"], "d": ["Pécs, que obtivera privilégios de Fernando em 1528, passou pouco depois para o lado de Szapolyai; o rei János permaneceu algum tempo na cidade em 1533. Com a queda de Buda em 1541, a cidade voltou novamente para o lado de Fernando.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Conquista de Trípoli", "8c659986"], "d": ["Trípoli foi tomada aos cavaleiros de São João; a costa central do Norte de África tornou-se otomana. Outros lugares incorporados na mesma data: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Conquista de Timișoara", "e9fd4995"], "d": ["Foi tomada a região do Banato e criado o Beylerbeylik de Timișoara.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Conquista definitiva de Tunes", "7bbd11bc"], "d": ["Tunes, sob controlo espanhol-hafsida, passou definitivamente à administração otomana; a linha do Norte de África ficou completa. Outros lugares incorporados na mesma data: Kayrevan, Gabes, Sfaks.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Conquista de Kanizsa", "0c7b6aa3"], "d": ["Kanizsa foi tomada na Longa Guerra; no ano seguinte a defesa de Tiryâki Hasan Paşa tornou-se lendária.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Começou a campanha de Uyvar — Fâzıl Ahmed Paşa marchou de Edirne contra a Áustria", "306a86db"], "d": ["Quando a Áustria atacou a Transilvânia e tomou as fortalezas de Székelyhíd e Kolozsvár, Istambul decidiu fazer campanha contra os Habsburgos. O grão-vizir Köprülüzâde Fâzıl Ahmed Paşa partiu de Edirne em 13 de abril de 1663. Em Belgrado chegou o pedido de paz da Áustria, mas em duas conversações em Osijek as condições otomanas foram rejeitadas. Na consulta em Buda, o objetivo foi também fixado em Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Conquista de Uyvar", "ce289470"], "d": ["Foi tomada Uyvar, fortaleza-chave da Hungria setentrional; a expressão 'forte como um turco diante de Uyvar' passou às línguas europeias. Depois de Uyvar, também Nitra e Léva se renderam com breve resistência; ambas foram recuperadas por De Souches na primavera de 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Recuperação da Moreia", "9b6460f1"], "d": ["A Moreia, deixada a Veneza em Karlowitz, foi recuperada numa só campanha. Outros lugares incorporados na mesma data: Balyabadra (Patras), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Segunda perda de Belgrado — cerco do príncipe Eugénio", "6a194354"], "d": ["Depois do desastre de Varadin e da perda de Timișoara, o príncipe Eugénio sitiou Belgrado; quando o exército de socorro que veio salvar a cidade foi também desbaratado, a fortaleza rendeu-se. A cidade, que fora recuperada em 1690 depois de Karlowitz, perdeu-se assim de novo e a linha de defesa do Danúbio ruiu. Belgrado só poderia ser recuperada vinte e dois anos depois, com o Tratado de Belgrado de 1739. Outros povoamentos perdidos na mesma data: Semendire.", "3bf3f600"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Queda de Özi", "90a67a6c"], "d": ["Özi, fortaleza-chave a norte do mar Negro, passou para as mãos da Rússia num assalto sangrento; a população da cidade foi passada a fio de espada.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Tratado de Bucareste — perda da Bessarábia", "932da4d6"], "d": ["Com o tratado que pôs fim à guerra russa de 1806-1812, o território a leste do Prut (Bessarábia) foi deixado à Rússia. Outros povoamentos perdidos na mesma data: Akkirman, Kili, Hotin, Bender, İsmail.", "a4c3a1fb"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Tratado de Edirne", "b3a8fe4c"], "d": ["No fim da guerra em que o exército russo entrou em Edirne, perdeu-se o delta do Danúbio; a autonomia/independência da Grécia foi reconhecida de facto. Outros povoamentos perdidos na mesma data: İbrail, Anapa, Ahıska. Embora o tratado tenha devolvido território, não pôs imediatamente fim à ocupação: a Valáquia-Moldávia e Silistre permaneceram, como penhor, sob administração russa até ao pagamento da indemnização de guerra — é por isso que estes lugares aparecem no mapa como ocupados também depois de 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Édito de autonomia para a Sérvia — knezado hereditário e condição da guarnição", "6a5d901d"], "d": ["O hatt-ı hümâyun emitido em conformidade com a disposição do Tratado de Edirne relativa à Sérvia reconheceu Miloš Obrenović como knez hereditário e fez da Sérvia um principado autónomo, livre nos assuntos internos e ligado externamente aos otomanos. Disposições: o knezado passaria de pai para filho, o imposto anual seria pago em montante fixo, a assembleia sérvia estabeleceria a sua administração interna, a Igreja seria autónoma; em contrapartida, permaneceriam guarnições otomanas nas fortalezas de Belgrado, Semendire, Šabac, Böğürdelen e Fethülislâm. Esta estrutura dual durou até à retirada das guarnições em 1867. No mapa, a cidade de Belgrado integra-se nesta data na Sérvia autónoma; a fortaleza de Kalemegdan é mostrada com guarnição otomana até 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Chipre deixado à administração inglesa", "423da3ee"], "d": ["Em troca de uma aliança contra a ameaça russa, a administração de Chipre foi transferida para a Inglaterra; juridicamente permaneceu território otomano. Outros povoamentos perdidos na mesma data: Lefkoşa, Magosa.", "04ce99ee"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Cedência da Tessália à Grécia", "ac614d24"], "d": ["Em conformidade com as decisões do Congresso de Berlim, a Tessália e os arredores de Narda foram cedidos à Grécia. Outros povoamentos perdidos na mesma data: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia).", "850edaa2"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Incorporação da Rumélia Oriental na Bulgária", "ee43f137"], "d": ["A província autónoma da Rumélia Oriental foi ligada à Bulgária por um golpe; a Sublime Porta aceitou o facto consumado.", "41e57063"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Batalha de Domokos", "9c6f29a5"], "d": ["Na Guerra Otomano-Grega de 1897, o exército alcançou uma vitória decisiva em Domokos; por pressão diplomática, os ganhos territoriais ficaram limitados.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomia de Creta", "2e764881"], "d": ["Apesar de a Guerra Otomano-Grega ter terminado com vitória otomana, a Inglaterra, a Rússia, a França e a Itália proclamaram em 18 de dezembro de 1897 a autonomia de Creta; a ilha seria uma província neutra e autónoma sob soberania otomana. Depois de 6 de novembro de 1898, a bandeira turca deixou de ser hasteada em Candia e em Kissamos; com a entrada em funções, em 22 de dezembro de 1898, do príncipe George, filho do rei grego, como alto-comissário, Creta saiu de facto da administração otomana (separou-se oficialmente em 1913). Outros povoamentos perdidos na mesma data: Kandiye (Girit), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Independência da Bulgária e anexação da Bósnia", "393feaa4"], "d": ["Na confusão do período constitucional, a Bulgária declarou a sua independência e a Áustria-Hungria anexou a Bósnia-Herzegovina.", "6b7e2450"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Recuperação de Edirne", "536e5599"], "d": ["Na II Guerra dos Balcãs, o exército atravessou o Maritsa e recuperou Edirne sem combate. Outros lugares incorporados na mesma data: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Vitória de Kut al-Amara", "98b972bc"], "d": ["A divisão inglesa sitiada em Kut rendeu-se com o seu comandante e 13 mil soldados — uma das maiores vitórias otomanas da Primeira Guerra Mundial.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Perda de Bagdade", "2c18a816"], "d": ["A Bagdade otomana de 383 anos passou ao exército inglês. Outros povoamentos perdidos na mesma data: Kerbelâ.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Perda de Jerusalém", "94067617"], "d": ["A Jerusalém otomana de 401 anos foi entregue sem poder ser defendida.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Perda de Damasco", "ed177b68"], "d": ["Com o colapso da frente da Palestina, Damasco foi evacuada; o domínio otomano de quatro séculos na Síria terminou. Outros povoamentos perdidos na mesma data: Hama, Humus.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Rendição de Medina", "76b505f6"], "d": ["Setenta e dois dias depois do armistício, a resistência de Fahreddin Paşa, o 'Tigre do Deserto', terminou por vontade do sultão; a última unidade otomana no Hejaz depôs as armas.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Ocupação de Esmirna", "e32e5e77"], "d": ["O exército grego desembarcou em Esmirna; a resistência, iniciada com o primeiro tiro, acendeu o rastilho da Luta Nacional. Aydın foi ocupada em 27 de maio de 1919 (item separado).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Ocupação oficial de Istambul", "a8e98ada"], "d": ["As forças da Entente ocuparam oficialmente Istambul e o Meclis-i Meb'ûsan foi dissolvido; os deputados dirigiram-se a Ancara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Tratado de Kars", "bb32d4e0"], "d": ["Entre a TBMM e as repúblicas do Cáucaso foi traçada a fronteira oriental tal como é hoje.", "fe736259"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["A tomada do emirado de Hail pelas forças sauditas-wahhabitas — a administração estava nas mãos da família Ibn Ali, da tribo Abde", "2d29ceb9"], "d": ["Quando as forças do Primeiro Estado Saudita tomaram o emirado de Hail, a administração da cidade estava nas mãos da família Ibn Ali, da tribo Abde, da confederação Shammar. Esta família governou Hail até 1835, quando Abdullah b. Reşîd tomou o emirado; a dinastia Reşîdî só foi fundada nessa data. No atlas, Hail aparecia até hoje sem dono até 1836, quando a fonte dá o nome do emir da cidade em 1820.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["A passagem das ilhas do Quarnaro para o Reino de Itália de Napoleão e das Bocas de Cattaro para a administração russa", "c5e411c8"], "d": ["Depois do Tratado de Pojun, as ilhas do Quarnaro — ao contrário da Dalmácia — foram ligadas não diretamente à França, mas ao Reino de Itália de Napoleão; só entraram nas Províncias Ilíricas em 1809. Nas Bocas de Cattaro, a administração austríaca terminou e entre 1806 e 1807 foi estabelecida a administração russa; as Bocas só passaram à França em 1807. Estas duas distinções não podem ser cobertas por uma única janela 'França' do atlas.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["A passagem da Dalmácia para a administração francesa — a aplicação do Tratado de Pojun (Presburgo)", "00bfe4f6"], "d": ["O Tratado de Pojun (Bratislava/Presburgo) de 26 de dezembro de 1805 forçou a Áustria a renunciar à Ístria, à Dalmácia e a todas as ilhas do Adriático. A França assumiu de facto a administração em fevereiro de 1806; Zadar permaneceu como centro do provedor-geral, e entre 1806 e 1810 este cargo foi exercido pelo veneziano Vicenzo Dandolo. A Dalmácia foi incorporada nas Províncias Ilíricas depois do Tratado de Schönbrunn de 1809. Terminou assim a primeira administração austríaca, que durava desde 1797 — no atlas, este período aparecia até hoje como austríaco ininterrupto.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["A recuperação das Províncias Ilíricas e da Dalmácia pela Áustria — o fim da administração napoleónica", "1b2ac942"], "d": ["No fim de 1813, as tropas habsburgas retomaram a região a sul do Sava e foi restabelecida a antiga organização da fronteira; o exército austríaco entrou na Ístria em outubro de 1813. Karlovac passou, depois dessa data, a fazer parte do Reino Austríaco da Ilíria. O período da administração francesa na Dalmácia encerrou-se também em 1813. A pertença da região à Áustria foi oficialmente confirmada pelas decisões da Paz de Paris de 1814 e do Congresso de Viena de 1815.", "a5c337df"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["A retoma de Damieta aos franceses — evacuação da fortaleza de Lesbe", "06b1e7b0"], "d": ["Uma força comandada por İbrâhim Paxá, do exército do grão-vizir, foi enviada a Damieta. Na manhã de 14 de maio, quando estava preparado o assalto à fortaleza de Lesbe, que protegia Damieta, verificou-se que a fortaleza fora evacuada pelos franceses e que a guarnição se retirara; tomaram-se também duas pequenas fortalezas ligadas a ela. Damieta foi, depois de Rosetta, que caíra em abril, a segunda cidade da foz do Nilo a sair do controlo francês.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Receção do Cairo aos franceses — a capitulação de Belliard", "7a11bb5e"], "d": ["Durante a operação conjunta das forças otomanas e britânicas contra o Egito, o general Belliard, comandante das forças francesas no Cairo, assinou a capitulação. Com o Cairo, também Suez, que os franceses tinham tomado em novembro de 1798, saiu do controlo francês. O encerramento da ocupação concluiu-se dois meses depois em Alexandria, e a evacuação do país prolongou-se até outubro.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Receção de Alexandria aos franceses — a capitulação de Menou", "cd50663c"], "d": ["O general Menou, comandante-chefe do Exército do Oriente, foi sitiado em Alexandria a 17 de agosto; a 21 de agosto, os ingleses tomaram o forte Marabout, perto da cidade, e a 31 de agosto Menou assinou a capitulação do exército. O regresso das tropas francesas a França começou a 2 de setembro. Assim, a ocupação, iniciada com o desembarque em Alexandria em junho de 1798, terminou na cidade em que começara.", "22e807c1"]},
"OLAYLAR_ORTADOGU_0919:1801-01-01:0":{"b": ["As tribos dos arredores de Tâif entram na influência uáabita — Türabe e Hurma separam-se do Xerifado de Meca", "d3b644be"], "d": ["As tribos dos arredores de Tâif, ligadas ao xerife de Meca Gālib, entraram em 1801 na influência uáabita; o emir de Dir'iye entregou-as à administração do xeque beduíno Osman el-Mudâyifî, cunhado e inimigo do Xerife. Os oásis de Türabe e Hurma, a leste, passaram também nesta faixa para o lado saudita. Foi o prelúdio da tomada de Tâif pelos uáabitas em fevereiro de 1803 e, depois, de Meca.", "4fe448d3"]},
"OLAYLAR_ORTADOGU_0919:1816-01-01:0":{"b": ["As guarnições egípcias retiram-se de Türabe, Bîşe e Rânye, no sul do Hejaz", "72b87aa1"], "d": ["Nos meses que se seguiram à paz de Tosun Paxá com os uáabitas e ao seu regresso ao Cairo em novembro de 1815, rebentou a confusão no sul do Hejaz; as guarnições de Mehmed Ali Paxá, de Kavala, foram obrigadas a retirar-se de Bîşe, Rânye e Türabe. A partida de İbrâhim Paxá do Cairo, em agosto de 1816, para uma nova campanha seguiu-se a esta retirada. Quem governou Türabe até à queda de Dir'iye (1818) não está escrito na fonte.", "90e76189"]},
"OLAYLAR_ORTADOGU_0919:1819-08-13:0":{"b": ["A guarnição egípcia retira-se de Süleymiye, em Harc, e chega a Menfûha — o sul do Najd fica sem chefe", "2743f70d"], "d": ["O posto egípcio que İbrâhim Paxá colocara em Süleymiye, em Harc, depois da destruição de Dir'iye, antes de partir por ordem de retirada do Paxá, mandou matar num banquete quatro xeques de Dilem e foi cercado pelos beduínos. A guarnição salva chegou a Menfûha a 13 de agosto de 1819 e iniciou a marcha para Qasim. No sul do Najd não restou autoridade central; as iniciativas da família Saud não deram resultado até 1824.", "fc53fbd1"]},
"OLAYLAR_P0043A:1456-01-01:0":{"b": ["Şehirköy volta ao domínio otomano — morte de Đurađ Branković", "e37156d1"], "d": ["Şehirköy, tomada em 1443 pelo exército cruzado e deixada aos sérvios por Murad II depois do Tratado de Edirne-Szeged de 1444, voltou em 1456 ao domínio otomano com a morte do déspota sérvio Đurađ Branković. No mesmo ano e pela mesma razão, também Niš entrou definitivamente na administração otomana; a linha do vale do Nišava que se abre para a estrada de Sófia ficou assim completa. O tratado fora assinado por dez anos e, depois de Varna (1444) e do Segundo Kosovo (1448), a vida do Despotado durou apenas o tempo da vida de Branković.", "4b6ec617"]},
"OLAYLAR_P0043B:1514-03-20:0":{"b": ["Selim I, o Severo, parte de Edirne para a Campanha de Çaldıran", "1f7921f7"], "d": ["Selim I, o Severo, que deixara como regente em Istambul o seu filho, o príncipe Süleyman, de Manisa, partiu de Edirne para a campanha que organizara contra o Estado Safávida. O exército, atravessando a Anatólia pela linha Sivas-Erzincan-Erzurum, enfrentaria no fim de agosto, em Çaldıran, as forças de Şah İsmail.", "430f5ccc"]},
"OLAYLAR_P0043KIRIM:1526-01-01:0":{"b": ["A fortaleza de Kızıkermen (Gazi Kerman) e a margem direita do Dniepre passam para o controlo otomano direto", "56a28224"], "d": ["A fortaleza de Kızıkermen e a margem direita do Dniepre, que o Canato da Crimeia mantinha desde meados do século XV, passaram nesta data para o controlo direto do Estado Otomano; a fortaleza transformou-se num posto avançado otomano na extremidade norte da estepe. Ao contrário do território do Canato da Crimeia em redor de Bahçesaray e Or Kapı, a administração de Kızıkermen estava diretamente nas mãos otomanas.", "a0eaba40"]},
"OLAYLAR_P0043KIRIM:1776-12-03:0":{"b": ["Prozorovsky ocupa Or Kapı — as forças russas permanecem em Orkapı até à anexação", "afdfe804"], "d": ["Quando o general Prozorovsky, que marchava para colocar Şâhin Giray no trono da Crimeia, chegou à linha de Perekop, Devlet Giray, o kaymakam e os tártaros tinham-se retirado da cidade; Prozorovsky ocupou sem combate a fortaleza de Or e a linha de Perekop. Os russos instalaram-se em Or Kapı e ali permaneceram até à anexação da Crimeia em 1783.", "2c53b49b"]},
"OLAYLAR_P0043KIRIM:1791-07-26:0":{"b": ["Ocupação de Anapa pelos russos (terceiro cerco)", "e6a7d6d5"], "d": ["A fortaleza de Anapa, construída em 1781 sob a administração de Ferah Ali Paxá, foi sitiada três vezes pelos russos durante a guerra; no termo do terceiro cerco foi ocupada, a 26 de julho de 1791. A ocupação foi provisória — como pelo Tratado de Iași (1792) se aceitaram no Cáucaso as antigas fronteiras, a fortaleza foi devolvida ao Estado Otomano.", "6f3b16fa"]},
"OLAYLAR_P0043KIRIM:1828-06-24:0":{"b": ["Entrega de Anapa por Osman Paxá aos russos", "3ccbdd1d"], "d": ["Na fase de abertura da Guerra Otomano-Russa de 1828-29, Anapa foi sitiada e as forças otomanas da fortaleza, sob o comando de Osman Paxá, entregaram-se aos russos a 24 de junho de 1828. Desta vez a entrega foi duradoura: pelo Tratado de Edirne, assinado no ano seguinte (14 de setembro de 1829), Anapa e o Cáucaso saíram oficialmente do domínio otomano.", "d49b4078"]},
"OLAYLAR_P0044:1556-01-01:0":{"b": ["Turgut Reis torna-se beylerbei de Trípoli de Barbaria — o eyalet alarga-se a leste até Tobruk e Derna", "160fa43c"], "d": ["Depois da conquista de Trípoli de Barbaria em 1551, Turgut Reis chegou a Trípoli de Barbaria, em Cemâziyelevvel de 963 (março de 1556), com o título de beylerbei. Durante o seu governo de nove anos, esforçou-se por desenvolver e fortificar o eyalet, levou a administração otomana, a sul, até ao Fezzan e, alargando as fronteiras para leste, tomou Tobruk e Derna, na costa de Barca. Assim, o eyalet de Trípoli de Barbaria passou a abranger a faixa costeira que se estende até à fronteira do Egito.", "44cf4583"]},
"OLAYLAR_P0044:1556-01-01:1":{"b": ["O Czarado de Moscovo toma Astracã — o Baixo Volga entra sob controlo russo", "d02abd83"], "d": ["O Czarado de Moscovo, tomando em 1556 também Astracã, fez, nas palavras do TDV, 'um lance que teria consequências muito importantes para o futuro'; com a ocupação do Canato de Astracã, o Baixo Volga entrou sob controlo russo. O cã da Crimeia Devlet Giray, embora quisesse impedir estas ocupações, não teve êxito. Os otomanos responderam a este desenvolvimento em 1569 com a campanha de Astracã; mas, não tendo êxito no controlo da região do Baixo Volga, deixaram ao cã da Crimeia a luta contra o Czarado de Moscovo.", "7e08ba29"]},
"OLAYLAR_P0044:1556-07-16:0":{"b": ["Conquista de Kostajnica e Novi — duas fortalezas da linha do Una", "2093e452"], "d": ["Kostajnica, sitiada no verão de 1556 por Malkoç Bey, era defendida pelo capitão Pankracije Lusthaller com mais de 60 soldados; a fortaleza foi entregue apenas um dia depois do início do cerco, a 16 de julho, e Lusthaller foi acusado de ter vendido a fortaleza. Pouco depois, Novi foi também tomada e incendiada; assim, as duas mais importantes fortalezas sobre o Una passaram para mãos otomanas de uma só vez. No mesmo ano, foi fundado em Viena o Conselho de Guerra da Corte (Hofkriegsrat), que dirigiria a partir do centro a defesa da fronteira.", "b985cbdf"]},
"OLAYLAR_P0044:1574-01-01:0":{"b": ["Mâku passa para os otomanos — İvaz Bey dos Mahmûdî encarregado de construir a fortaleza", "5932ad38"], "d": ["No ano de 1574, o Estado Otomano encarregou İvaz Bey, chefe da tribo curda dos Mahmûdî, de tomar Mâku aos iranianos e de construir aí uma fortaleza. Esta fortaleza, na extremidade oriental do eyalet de Van, ocupou um lugar importante nos acontecimentos ocorridos na região durante o período otomano.", "bd663d7c"]},
"OLAYLAR_P0044:1840-01-01:0":{"b": ["Emitido o primeiro papel-moeda otomano (kâime)", "d2e5e192"], "d": ["Nos primeiros anos do Tanzimat, na procura de receitas para as finanças, foi aceite, por proposta de Ârif Hikmet Bey, depois xeique do Islão, a prática do kâime, uma forma desenvolvida do sistema esham. As primeiras kâime, no montante total de 160.000 liras (32.000 bolsas), foram emitidas, por necessidade urgente de dinheiro, sem esperar pela impressão, manuscritas, no tempo do ministro das Finanças Sâib Paxá, provavelmente em junho de 1840. Estes papéis, com valor de moeda corrente, tinham um prazo de circulação de oito anos e juro de 12,5% ao ano; não tinham cobertura, só os seus juros foram garantidos com o rendimento da alfândega de Istambul. O povo não acolheu favoravelmente este dinheiro a que não estava habituado e as kâime manuscritas tornaram-se rapidamente alvo de falsificadores.", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["Tomada de Malaca pelos portugueses", "e1556746"], "d": ["Malaca, fundada na década de 1390, tornara-se o porto mais movimentado da região para o comércio marítimo entre a China, a Índia e o Ocidente e, como centro do Sultanato de Malaca, também o principal foco da difusão do Islão nas ilhas vizinhas. O português Afonso de Albuquerque tomou a cidade a 10 de agosto de 1511; a cidade foi saqueada, as suas mesquitas, os túmulos da dinastia e os outros edifícios de alvenaria foram demolidos para que as pedras fossem usadas na construção da fortaleza. Malaca, sob administração portuguesa, não conseguiu manter a antiga supremacia comercial; os mercadores muçulmanos voltaram-se para o porto do Sultanato de Aceh, na Sumatra. Por causa dos ataques dos portugueses instalados em Malaca contra Aceh, o sultão de Aceh Alâeddin Riâyet Şah pediu ajuda em 1565 a Solimão, o Legislador.", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["Şâhverdi, senhor de Luristão, declara fidelidade a Şah Abbas", "85791f94"], "d": ["Şâhverdi, senhor de Luristão, que em 1589 se submetera aos otomanos como súbdito do beylerbei de Bagdade, foi obrigado, segundo a narrativa do historiador safávida İskender Bey Münşî, a declarar no ano 1000 (1591-92) fidelidade à coroa safávida. A mesma fonte escreve que nestes anos ele ia e vinha entre os dois lados, incomodava os governadores de Hamadã e fazia incursões a Burûcird, e que em 1002 (1593-94) Şah Abbas ocupou Hürremâbâd e nomeou um governador para a cidade. A Enciclopédia do Islão do TDV, por seu lado, situa em 1603 a plena ligação aos safávidas de Luristão, que fora ligado à administração otomana pelo Tratado de Istambul de 1590. As duas tradições dão datas diferentes; este item mostra a declaração de fidelidade da tradição safávida, o item de 1603 mostra a perda definitiva. No mapa, não há mudança de dono com este item: Luristão aparece do lado otomano até 1603.", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["Passagem definitiva de Luristão para os safávidas", "4c5cf67b"], "d": ["Luristão, ligado à administração otomana pelo Tratado de Istambul (Ferhad Paşa) de 1590, foi plenamente ligado aos safávidas em 1603 pelo xá Abbas I. O historiador safávida İskender Bey Münşî escreve, por seu lado, que Hürremâbâd fora ocupada antes por Şah Abbas, em 1002 (1593-94), e que lhe fora nomeado um governador safávida; esta diferença entre as duas tradições não está resolvida. No mesmo ano, também a fortaleza otomana de Nihâvend, a norte de Luristão, passou para as mãos de Şah Abbas; o governador de Hamadã, Hasan Han, arrasou a fortaleza.", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["A Companhia Catalã entra ao serviço de Bizâncio — início da campanha da Anatólia", "6623e7db"], "d": ["O Império Bizantino, que perdia território para os beiliques turcos na Anatólia Ocidental, tomou ao seu serviço, como soldados assalariados, uma força catalã de cerca de 6500 homens comandada por Roger de Flor. Segundo o artigo Bizans do TDV, a força veio em auxílio do império em 1303 e, no ano seguinte, libertou Alaşehir, sitiada pelos Germiyanoğulları. Mas a companhia começou rapidamente a saquear os lugares por onde passava; Bizâncio fê-la passar à Trácia e mandou matar Roger de Flor em 1305.", "87b98a94"]},
"OLAYLAR_P0049:1538-11-27:0":{"b": ["O senhor do Hadramaute e de Shihr reconhece o domínio otomano — regresso da campanha da Índia de Hadım Süleyman Paxá", "b5cb9363"], "d": ["Hadım Süleyman Paxá, que regressava do cerco de Diu, tocou a 27 de novembro de 1538 o Porto de Shihr; quando o senhor do Hadramaute e de Shihr aceitou o domínio otomano, passou a Aden. O Hadramaute foi organizado como sanjaco ligado ao Iémen, mas os chefes da tribo Kesîrî continuaram a manter a administração na região. Esta subordinação durou até à retirada dos otomanos do Iémen em 1635.", "cff04bbb"]},
"OLAYLAR_P0049:1555-05-29:0":{"b": ["O beilique de Mingrélia (Dadyan) deixado à zona de influência otomana", "ea54e8ea"], "d": ["Pelas disposições do Tratado de Amasya que dividiam a Geórgia, o beilique de Dadyan (Mingrélia e Svanécia), na Geórgia ocidental, foi deixado, juntamente com Imerécia e Güryel, à zona de influência otomana. No mapa, Zugdidi, centro da Mingrélia, aparece a partir deste dia como beilique súbdito dos otomanos; a declaração efetiva de obediência viria em 1578.", "1724aa10"]},
"OLAYLAR_P0049:1578-08-09:0":{"b": ["O atabegado de Ahıska entra na administração otomana — Altunkale, Hırtıs e Ahılkelek", "024bb326"], "d": ["Logo depois de Lala Mustafa Paxá ter derrotado em Çıldır as forças de vanguarda safávidas, também os territórios em mãos dos atabegues georgianos passaram para a administração otomana. Dedis İmedi, que mantinha Altunkale e arredores, e os seus filhos declararam a sua obediência; o sancakbeyi de Ardahan tomou Çıldır e Tümük, e outras tropas otomanas tomaram Hırtıs e Ahılkelek. A Menûçihr e ao seu irmão foi deixado um sanjaco a cada um e o resto do país do atabegado foi ligado à administração direta. Ahıska será depois o centro do eyalet de Çıldır, recém-fundado; Menûçihr, que veio a Istambul, se fez muçulmano e tomou o nome de Mustafa, foi posto à frente deste eyalet a 1 de julho de 1579.", "23731679"]},
"OLAYLAR_P0049:1579-07-26:0":{"b": ["Kılıç Ali Paxá constrói a Fortaleza de Faş (Poti) — base otomana na foz do Rioni", "f729ba95"], "d": ["O kapudan-paxá Kılıç Ali Paxá construiu, a 26 de julho de 1579, a Fortaleza de Faş no lugar em que o rio Rioni (Faş) desagua no Mar Negro.", "13606f9d"]},
"OLAYLAR_P0049:1587-01-01:0":{"b": ["Fundado o eyalet de Gori — administração otomana direta no oeste de Kartli", "9a7c8bc5"], "d": ["Em 1578, os beis georgianos das regiões de Gori e Muhran tinham-se submetido aos otomanos. Em 1587 foi fundado o eyalet de Gori, no oeste de Kartli, e a região foi ligada à administração otomana direta. A Fortaleza de Gori, perdida durante a revolta do georgiano Simon, foi retomada em 1601; a administração otomana terminou em 1603 com a campanha de Şah Abbas.", "7ee17c2b"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["As incursões de Miguel, o Valente, às fortalezas do Danúbio — Ruse incendiada, Brăila tomada, Silistra saqueada", "d0b83f6a"], "d": ["Miguel, o Valente, voivoda da Valáquia, que aderira à Santa Liga, lançou-se no inverno de 1594-95 contra as fortalezas e cidades sob administração otomana direta nas margens do Danúbio. Segundo o artigo Rusçuk do TDV, em fevereiro de 1595, embora não tenha tomado a fortaleza, apoderou-se da cidade e incendiou-a. Segundo o artigo İbrâil, tomou İbrâil, na margem esquerda do Danúbio, e a cidade permaneceu em seu poder até 1601; o artigo Murad III escreve também que o exército valaco incendiou a fortaleza de İbrâil e se estendeu até Silistra. Segundo um registo de recenseamento mencionado no artigo Silistre, o exército valaco atravessou o Danúbio na primavera de 1595 e saqueou Silistra; a fortaleza da cidade foi destruída e não pôde ser usada durante muito tempo. No mesmo verão, Koca Sinan Paxá partiria em campanha contra a Valáquia.", "c115852f"]},
"OLAYLAR_P0049:1603-01-01:0":{"b": ["Şah Abbas retoma Tbilisi — fim da administração otomana em Kartli e Kakheti", "a6995ea8"], "d": ["O xá Abbas I retomou Tbilisi aos otomanos em 1603 e proclamou Kartli canato; também em Kakheti foi estabelecida a administração safávida. Terminou assim a administração otomana na Geórgia Oriental, que começara em 1578 com a campanha de Lala Mustafa Paxá; Tbilisi só voltaria a passar para mãos otomanas em 1723.", "e37dcbfc"]},
"OLAYLAR_P0049:1640-01-01:0":{"b": ["A Fortaleza de Faş (Poti) destruída pelas forças de Imerécia, Guria e Mingrélia", "3c3d4ed7"], "d": ["A Fortaleza de Faş foi arrasada em 1640 pelas forças de Imerécia, com a participação dos príncipes de Guria e da Mingrélia. A presença otomana na foz do Rioni foi interrompida até à reconstrução da fortaleza em 1724.", "2bb31f58"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["Começou a Campanha do Prut — na guerra otomano-russa de 1710-1711 o exército sai de Istambul", "3161364b"], "d": ["O ataque da Rússia a território otomano, o facto de o czar Pedro não cumprir as disposições do Tratado de Istambul de 1700 e os incitamentos do cã da Crimeia Devlet Giray levaram Ahmed III a declarar guerra à Rússia. Segundo o artigo Ahmed III do TDV, esta guerra, que seria depois conhecida como Campanha do Prut, começou de facto com a partida do exército otomano de Istambul a 9 de abril de 1711. O exército comandado por Baltacı Mehmed Paxá, juntando-se às forças da Crimeia, avançou para o rio Prut; a campanha terminaria em julho com o exército russo encurralado nas margens do Prut.", "49618c54"]},
"OLAYLAR_P0049:1724-03-01:0":{"b": ["Começou a reconstrução da Fortaleza de Faş (Poti)", "0afbc4b0"], "d": ["Por decisão tomada a 23 de dezembro de 1723, a reconstrução da arruinada Fortaleza de Faş começou em março de 1724; a construção concluiu-se em 1729.", "e9e6b3d8"]},
"OLAYLAR_P0049:1724-05-06:0":{"b": ["A região de Khoy, Kapan e Karadağ passa de novo para a administração otomana", "c52c94d1"], "d": ["Durante a campanha do Irão iniciada em 1723, Khoy e a região de Kapan e Karadağ passaram de novo para a administração otomana a 6 de maio de 1724 e foram registadas no recenseamento otomano em 1728.", "80dafa38"]},
"OLAYLAR_P0049:1733-08-17:0":{"b": ["Nâdir entra em Şemâhî — o centro de Şirvan sai do domínio otomano", "778a4988"], "d": ["Nâdir entrou a 17 de agosto de 1733 em Şemâhî, que coubera aos otomanos, com a parte central de Şirvan, pelo Tratado de Istambul de 24 de junho de 1724. A administração otomana no Cáucaso desagregou-se depois rapidamente; Gäncä e Tbilisi perderam-se em 1735.", "4ab61a36"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Ultimato ao enviado russo — o último passo para a Guerra Otomano-Russa de 1787-1792", "cb389693"], "d": ["A tensão que durava desde a anexação da Crimeia pela Rússia, em 1783, rompeu-se quando se descobriu que o consulado da Rússia em Alexandria incitava os beis mamelucos do Egito contra os otomanos. Segundo o artigo I. Abdülhamid do TDV, o Reîsülküttâb Süleyman Feyzi Efendi entregou a 27 de julho de 1787 um ultimato de sete artigos ao enviado russo em Istambul. A decisão de guerra foi tomada sem esperar pela resposta da Rússia e foi declarada em poucas semanas; o objetivo da guerra era recuperar a Crimeia.", "04debfa8"]},
"OLAYLAR_P0049:1809-11-27:0":{"b": ["As forças russas tomam a Fortaleza de Faş (Poti) — perdida a foz do Rioni", "c1241b5a"], "d": ["Durante a guerra otomano-russa de 1806-1812, o ataque russo de maio de 1809 fracassou; mas a fortaleza foi entregue aos russos a 27 de novembro de 1809.", "84e0aac2"]},
"OLAYLAR_P0049:1812-12-19:0":{"b": ["Em virtude do Tratado de Bucareste, a Fortaleza de Faş (Poti) devolvida aos otomanos", "6a3a8a0a"], "d": ["Em virtude do Tratado de Bucareste de 1812, a Fortaleza de Faş foi entregue ao Estado Otomano a 19 de dezembro de 1812.", "d59bceb8"]},
"OLAYLAR_P0049:1828-06-26:0":{"b": ["A Fortaleza de Faş (Poti) passa pela segunda vez para mãos russas — fica com a Rússia pelo Tratado de Edirne", "682d58f0"], "d": ["No início da guerra otomano-russa de 1828-1829, a Fortaleza de Faş foi entregue aos russos a 26 de junho de 1828. Pelo Tratado de Edirne de 14 de setembro de 1829, Poti, juntamente com Ahıska, Ahılkelek e Anapa, foi cedida à Rússia.", "364c160c"]},
"OLAYLAR_P0049:1915-07-25:0":{"b": ["Os ingleses ocupam Nâsıriye — frente do Eufrates", "669b979e"], "d": ["As forças britânicas, que avançavam de Baçorá ao longo do Eufrates, derrotaram as unidades otomanas a 24 de julho de 1915 e ocuparam Nâsıriye no dia seguinte. Baçorá caíra em novembro de 1914; Nâsıriye permaneceu ainda cerca de oito meses em mãos otomanas.", "bd125229"]},
"OLAYLAR_P0049:1919-04-12:0":{"b": ["Ocupação britânica de Kars — dissolvido o Governo do Cáucaso Sudoeste", "9004afc9"], "d": ["Em virtude da disposição do Armistício de Mudros sobre a retirada para as fronteiras de 1914, o exército otomano evacuara Kars. A população da região fundou a 5 de novembro de 1918 o Conselho Islâmico de Kars contra os ataques arménios e georgianos e, com o congresso de janeiro de 1919, transformou-o no Governo Provisório Nacional do Cáucaso Sudoeste. Segundo o artigo Kars do TDV, os ingleses ocuparam Kars a 12 de abril de 1919 e dissolveram este governo, prenderam os seus membros e enviaram-nos para o exílio, e deixaram o controlo da cidade aos arménios.", "06392190"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Ocupação italiana de Antália", "328331da"], "d": ["Quando, depois do Armistício de Mudros, as potências da Entente se instalavam nas zonas de ocupação na Anatólia, a Itália voltou-se para o sudoeste da Anatólia. Segundo o artigo Antalya do TDV, a cidade e os arredores foram ocupados pelos italianos a 29 de abril de 1919, com base nas disposições do armistício. A ocupação duraria cerca de dois anos.", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Libertação de Maraş — os franceses evacuam a cidade", "a57d884e"], "d": ["Maraş, ocupada pelos ingleses a 22 de fevereiro de 1919, fora deixada aos franceses a 29 de outubro de 1919 por um acordo entre os dois Estados. A atitude dos arménios nas tropas francesas e a descida da bandeira turca na fortaleza sublevaram a população; na cidade organizaram-se a Sociedade de Defesa dos Direitos e as Forças Nacionais. Segundo o artigo Kahramanmaraş do TDV, no termo dos combates, os franceses evacuaram a cidade a 11 de fevereiro de 1920 e começaram a retirar-se em direção a İslâhiye, e Maraş foi libertada a 11-12 de fevereiro. A cidade recebeu em 1925 a medalha da Independência.", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Libertação de Urfa — a guarnição francesa abandona a cidade", "c889488c"], "d": ["Em Urfa, ocupada pelos ingleses em março de 1919 e, cerca de sete meses depois, pelos franceses, a população revoltou-se contra as forças de ocupação a 7 de fevereiro de 1920. Segundo o artigo Şanlıurfa do TDV, depois de dois meses de combates, os franceses aceitaram a 10 de abril de 1920, nas condições de um acordo, evacuar Urfa e saíram da cidade no dia seguinte.", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["Começou a operação da Frente Leste — Kâzım Karabekir passa à ofensiva contra a Arménia", "151678df"], "d": ["Como o Tratado de Sèvres deixava à Arménia Erzurum, Trabzon, Van, Bitlis e Bingöl e os ataques arménios na região aumentavam, o governo da Grande Assembleia Nacional da Turquia autorizou a operação a 20 de setembro de 1920. Segundo o artigo Kâzım Karabekir do TDV, Karabekir, comandante da Frente Leste, deu ordem de ataque às suas unidades que mantinham os desfiladeiros do monte Soğanlı e começou a operação do leste a 28 de setembro. Foram tomadas Sarıkamış, Göle e Kağızman; a operação prosseguiria um mês depois com a libertação de Kars.", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Libertação de Kars — a Frente Leste entra em Kars", "4e578071"], "d": ["Segundo o artigo Kars do TDV, Kâzım Karabekir Paxá entrou em Kars a 30 de outubro de 1920 e a cidade foi libertada da administração arménia, cujo controlo os ingleses tinham deixado em 1919. O artigo Karabekir sublinha que esta foi a segunda libertação de Kars: a cidade fora tomada pela primeira vez aos arménios em abril de 1918. A Frente Leste, avançando, tomou Gümrü a 7 de novembro; a guerra terminou com o Tratado de Gümrü, a 3 de dezembro de 1920.", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Tomada de Gümrü — a Frente Leste avança para o interior da Arménia", "cfddf791"], "d": ["As tropas de Kâzım Karabekir Paxá, que prosseguiu a operação depois da libertação de Kars, tomaram Gümrü a 7 de novembro de 1920. As conversações com os arménios, que aceitaram o armistício, conduziram-se em Gümrü e a guerra terminou com o Tratado de Gümrü, assinado a 3 de dezembro de 1920.", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Tomada de Iğdır", "6e952d2e"], "d": ["A Frente Leste, cinco dias depois de tomar Gümrü, tomou também Iğdır, a 12 de novembro de 1920. Iğdır foi deixada à Turquia pelo Tratado de Gümrü de 3 de dezembro de 1920.", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Fim da defesa de Antep — a cidade, depois de dez meses de resistência, deixada aos franceses", "e080af8b"], "d": ["Antep, em que os ingleses entraram a 17 de dezembro de 1918, fora deixada aos franceses a 5 de novembro de 1919; a primeira resistência na linha Antep-Kilis foi dirigida por Şâhin Bey. Segundo o artigo Gaziantep do TDV, a população da cidade resistiu às forças francesas de 1 de abril de 1920 a 7 de fevereiro de 1921; quebrada a resistência, as forças da defesa retiraram-se e os franceses dominaram a cidade a 9 de fevereiro. A TBMM concedera à cidade, que resistira dez meses à ocupação, três dias antes, a 6 de fevereiro de 1921, o título de gazi. Antep seria evacuada a 25 de dezembro de 1921, depois do Tratado de Ancara.", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Libertação de Ardahan e Artvin", "b9e50d5e"], "d": ["Depois do Tratado de Gümrü, a Frente Leste voltou-se para a parte das três províncias que estava em mãos da Geórgia. Segundo o artigo Ardahan do TDV, no termo da luta contra os bandos georgianos e arménios, o sanjaco de Ardahan foi libertado, juntamente com Artvin, a 23 de fevereiro de 1921. O artigo Kâzım Karabekir escreve que, com este lance, foram recuperados os territórios das três províncias, com exceção das kazas de Çürüksu, Acara e Batum.", "1ee51ba4"]},
"OLAYLAR_P0049:1921-03-16:0":{"b": ["Tratado de Moscovo — a TBMM e a Rússia Soviética fixam a fronteira leste", "78d46573"], "d": ["A 16 de março de 1921 foi assinado o Tratado de Moscovo entre o governo da TBMM e a Rússia Soviética. Segundo o artigo Kars do TDV, com este tratado e com os ajustamentos de fronteira do Tratado de Kars de 13 de outubro de 1921, Kars ficou dentro das fronteiras do novo Estado turco. Segundo o artigo Ahıska, por seu lado, Ahıska foi ligada por este tratado à província de Tbilisi da República Socialista Soviética da Geórgia. A fronteira leste ficaria definitiva sete meses depois com o Tratado de Kars assinado com as repúblicas da Transcaucásia.", "afda4a36"]},
"OLAYLAR_P0049:1921-06-01:0":{"b": ["Os italianos começam a evacuar Antália", "f7a4eaa7"], "d": ["Segundo o artigo Antalya do TDV, a ocupação italiana, que durava desde 29 de abril de 1919, terminou quando os italianos começaram a evacuar a cidade a 1 de junho de 1921. Antália e os arredores ficaram assim livres da ocupação sem esperar pelo resultado militar da Luta Nacional.", "ffd82d73"]},
"OLAYLAR_P0050:1527-01-01:0":{"b": ["Dieta de Cetin — os nobres croatas elegem Fernando de Habsburgo rei da Croácia depois de Mohács", "55fc9d7e"], "d": ["Quando o trono ficou vago com a morte, em Mohács, do rei húngaro-croata Luís II, os nobres croatas reuniram-se em Cetin a 31 de dezembro de 1526 e, no dia de Ano Novo, proclamaram rei o arquiduque da Áustria Fernando. Nas palavras do TDV, os croatas fizeram esta eleição independentemente dos nobres húngaros; o documento da eleição baseava-se no motivo de não se separarem do Estado cristão perante as incursões otomanas. Assim, as fortalezas croatas vizinhas da Bósnia otomana foram ligadas à coroa da dinastia Habsburga; segundo o TDV, quando nos anos 1530 os Habsburgos começaram a organizar a região fronteiriça croata, o principal centro desta linha foi Bihać.", "5e7c69d8"]},
"OLAYLAR_P0050:1527-01-01:1":{"b": ["Breve administração otomana de Bihać — depois de Mohács e da queda de Jajce", "fd4118fe"], "d": ["Depois da vitória de Mohács, os otomanos tomaram na Bósnia Jajce, centro da zona-tampão húngara, e Banja Luka. Segundo o artigo Bihaç do TDV, depois da tomada da Fortaleza de Jajce, no ano seguinte a Mohács, Bihać passou por pouco tempo para a administração dos otomanos. Quando e como a fortaleza se perdeu não está escrito na fonte; o TDV apenas observa que nos anos 1530 os Habsburgos, ao organizarem a região fronteiriça croata, fizeram de Bihać, em mãos dos cristãos, o centro principal. A conquista duradoura de Bihać realizar-se-ia em 1592, com a campanha de Hasan Paxá, beylerbei da Bósnia.", "3421f09a"]},
"OLAYLAR_P0050:1814-01-28:0":{"b": ["Fim da administração francesa em Dubrovnik — as forças austríacas entram na cidade, antiga tributária otomana", "38d42444"], "d": ["Segundo o TDV, a República de Dubrovnik, sob proteção otomana desde 1365, fora extinta pelos franceses ao tomarem a cidade a 27 de maio de 1806. No inverno de 1813-1814, a população da cidade revoltou-se contra os franceses; a 3 de janeiro de 1814, o general-major austríaco Milutinović, que chegou a Gruž com dois batalhões croatas, cercou a guarnição; depois de quatro dias de bombardeamento, a guarnição francesa enviou um emissário ao general. Ao amanhecer de 28 de janeiro, as tropas austríacas e inglesas marcharam de Gruž para a cidade; a 31 de janeiro começou a funcionar na região uma administração austríaca provisória. A incorporação da cidade no território austríaco foi confirmada no Congresso de Viena de 1815.", "bb94e4af"]},
"OLAYLAR_P0050:1882-03-06:0":{"b": ["Proclamação do Reino da Sérvia — o antigo principado súbdito otomano transforma-se em reino", "7d90e712"], "d": ["O Principado da Sérvia, que conquistara a independência em 1878 e tomara nesse mesmo ano Niš aos otomanos, foi transformado em reino no tempo de Milan Obrenović. Pelo primeiro artigo da lei promulgada em Belgrado, o principado foi proclamado Reino da Sérvia e o príncipe Milan tornou-se rei com o nome de Milan I; a lei foi publicada no mesmo dia no jornal oficial Srpske novine. Assim, a Sérvia, que até 1878 era um principado ligado aos otomanos, ocupou nos Balcãs o seu lugar com o título de reino.", "628ac155"]},
"OLAYLAR_P0050:1920-07-01:0":{"b": ["Instaurada na Palestina a administração civil de mandato britânica — fim da administração militar nos territórios tomados aos otomanos", "c0d7b76a"], "d": ["Com a tomada de Gaza e, depois, de Jerusalém pelo general Allenby em 1917, terminara na Palestina o domínio otomano de quatrocentos anos e Jerusalém permanecera entre 1917 e 1920 sob administração militar britânica. A Conferência de San Remo de 1920 deu a Palestina ao mandato britânico; a Inglaterra, a partir de julho de 1920, estabelecendo na região uma administração civil de mandato, começou a governar o país por meio de um alto-comissário. À frente da administração civil esteve o alto-comissário Herbert Samuel. As revoltas árabes e os conflitos judaico-árabes iniciados no mesmo ano marcariam todo o período do mandato.", "52b7fc82"]},
"OLAYLAR_P0050:1922-03-15:0":{"b": ["Proclamado o Reino do Egito — o sultão Ahmed Fuâd toma o título de rei", "c6ad08d1"], "d": ["A Inglaterra, a 18 de dezembro de 1914, abolira unilateralmente os direitos de soberania do Estado Otomano sobre o Egito e pusera o país sob a sua proteção. Depois da guerra, como as negociações entre a Inglaterra e o Egito não deram resultado, a Inglaterra proclamou, por uma declaração igualmente unilateral, a 28 de fevereiro de 1922, o Egito como Estado independente. O sultão Ahmed Fuâd tomou, a 15 de março de 1922, o título de rei (melik) e foi proclamada a monarquia no Egito. O TDV considera esta independência formal; a constituição da ordem monárquica entraria em vigor a 19 de abril de 1923.", "f9b00023"]},
"OLAYLAR_P0051:1480-01-01:0":{"b": ["A fortaleza de Hacıbey (Kaçibey) sai das mãos da Lituânia", "382b51e3"], "d": ["O porto de Kaçibey, na costa noroeste do Mar Negro, fora fortificado no início do século XV pelo grão-duque da Lituânia Vytautas. Em 1480, a fortaleza saiu das mãos da Lituânia e recebeu o nome de Hacıbey. A costa passou, no fim do século XV, para o controlo do Canato da Crimeia, súbdito dos otomanos; a ligação da região à organização administrativa otomana direta é de 1538.", "cea3442c"]},
"OLAYLAR_P0051:1570-01-01:0":{"b": ["Gramota de Ivan IV aos cossacos do Don — o primeiro registo fiável do Exército Cossaco do Don", "16c0732e"], "d": ["As informações sobre a existência de cossacos no Don começam em meados do século XVI. Segundo a enciclopédia militar russa, a antiguidade do Exército Cossaco do Don conta-se a partir de 1570: nesse ano, o czar Ivan IV enviou uma gramota aos cossacos que viviam no Donets Setentrional, pedindo-lhes que ajudassem Ivan Novosiltsev, enviado como emissário ao sultão otomano por Azov, e prometendo recompensá-los em troca. Este é o primeiro registo fiável do serviço dos cossacos do Don ao Estado de Moscovo. O principal centro dos cossacos foi primeiro Razdory Superior e depois Cherkassk.", "3ce37828"]},
"OLAYLAR_P0051:1585-01-01:0":{"b": ["Moscovo estabelece em Voronezh uma guarnição avançada contra a estepe", "89c941fe"], "d": ["No fim do século XVI, a atual Ucrânia Sloboda e a bacia superior do Don eram uma estepe selvagem e despovoada pela qual passavam as incursões dos tártaros contra Moscovo. O governo de Moscovo estabeleceu nesta estepe uma série de guarnições avançadas; Voronezh foi fundada em 1585 como uma delas. A fortaleza foi, nas décadas seguintes, juntamente com Belgorod e Kursk, um dos primeiros elos da linha de defesa meridional de Moscovo.", "ceb11b6b"]},
"OLAYLAR_P0051:1596-01-01:0":{"b": ["Moscovo funda Belgorod, Oskol e Kursk como guarnições avançadas na estepe", "4ff3e225"], "d": ["O governo de Moscovo, avançando a fronteira sul contra as incursões da Crimeia, fundou em 1596 Belgorod, Oskol e Kursk como pontos de guarnição na estepe selvagem. Belgorod tornou-se desde esta data uma cidade-fortaleza e transformou-se no centro da linha de defesa de Belgorod, de 300 quilómetros, que se estenderia no século seguinte.", "50cb899c"]},
"OLAYLAR_P0052:1884-01-01:0":{"b": ["O sanjaco de Siirt transferido de Diyarbekir para o vilaiete de Bitlis — a kaza de Eruh e a aldeia de Şırnak ligadas também a Bitlis", "3922d040"], "d": ["Quando, depois do Tanzimat, se passou do sistema de eyalets ao de vilaietes, o sanjaco de Siirt, que permanecera ligado ao vilaiete de Diyarbekir, foi transferido em 1884 para o vilaiete de Bitlis. Segundo o artigo Şırnak do TDV, os territórios em que hoje se situa Şırnak ficaram assim dentro da kaza de Eruh, ligada ao sanjaco de Siirt do vilaiete de Bitlis. Şırnak era então uma pequena aldeia da kaza de Eruh; o seu nome aparece nos registos por volta do fim do século XIX, e o facto de ser centro da kaza fica para os primeiros anos da República. Estes territórios tinham sido incorporados nos otomanos em 1514, depois da Campanha de Çaldıran, e administrados dentro do sanjaco de Siirt do eyalet de Diyarbekir.", "1539b089"]},
"OLAYLAR_P0053:1624-01-01:0":{"b": ["Mossul e Quircuque passam para mãos safávidas — depois da queda de Bagdade", "86e176c8"], "d": ["Şah Abbas, que, no termo dos acontecimentos iniciados com a revolta de Bekir Subaşı, tomou Bagdade, enviou o seu comandante Karçakay Han com as suas forças sobre Mossul e Quircuque. O governador de Mossul, Çerkez Ahmed Paxá, só pôde defender a cidade alguns dias; Mossul, tal como Quircuque, passou para o domínio do Irão e foi nomeado governador Kāsım Han. Quando Sipahi Küçük Ahmed, que comandava a força de vanguarda de Hâfız Ahmed Paxá, apareceu diante de Mossul, Kāsım Han deixou a cidade e retirou-se para Bagdade, mas, com a contraofensiva de Şah Abbas, Mossul voltou em 1624 para as mãos dos safávidas.", "81474bd6"]},
"OLAYLAR_P0053:1625-01-01:0":{"b": ["Libertação de Mossul dos safávidas — a campanha de Bagdade de Hâfız Ahmed Paxá", "1f9ca4a1"], "d": ["Murad IV enviou sobre Bagdade o exército comandado pelo grão-vizir Hâfız Ahmed Paxá. Quando o exército estava nos arredores de Diyarbekir, a força de vanguarda de Çerkez Hasan, beylerbei de Karaman, perseguiu até Quircuque os partidários do Irão reunidos em Altınköprü e pôs sob controlo a região, incluindo Quircuque; os safávidas, desta vez, não puderam também manter Mossul por muito tempo. Hâfız Ahmed Paxá chegou no início de setembro primeiro a Mossul e depois a Quircuque e sitiou Bagdade a 13 de novembro de 1625; o cerco ficou sem resultado e Bagdade permaneceu em mãos safávidas. O artigo Kerkük do TDV, por seu lado, liga a retoma da cidade aos safávidas a 1630, a Hüsrev Paşa.", "ad32f3ae"]},
"OLAYLAR_P0053:1630-03-16:0":{"b": ["Hüsrev Paşa reconstrói a Fortaleza de Gülanber em Shahrizor — o beylerbeylik de Shahrizor", "9511853c"], "d": ["O grão-vizir Hüsrev Paşa, que partira para a campanha de Bagdade, depois de ter permanecido muito tempo em Mossul por causa das chuvas torrenciais, voltou-se para Shahrizor. Começou a reconstrução da Fortaleza de Gülanber, que na invasão de Şah Abbas fora demolida por sua ordem; Shahrizor foi de novo feito centro de beylerbeylik e na fortaleza foi deixado como beylerbei Arnavud Mustafa Paxá. Hüsrev Paşa submeteu as tribos da região, tomou a Fortaleza de Mihriban e, a 5 de maio de 1630, infligiu perto desta fortaleza pesadas perdas ao exército safávida.", "ff2c7cea"]},
"OLAYLAR_P0055:1369-01-01:0":{"b": ["Timurtaş Bey toma no vale do Tundja Kızılcaağaç Yenicesi (Elhova) e Yanbolu", "2c2aebea"], "d": ["Durante a operação de Murad I contra a Bulgária e Bizâncio, Kara Timurtaş Bey foi enviado ao vale do Tundja; tomou Kızılcaağaç Yenicesi e Yanbolu e regressou a Edirne com abundante saque.", "e2ca7962"]},
"OLAYLAR_P0055:1371-09-26:0":{"b": ["O Principado dos Dejanović (Kostadin-ili) torna-se vassalo otomano", "54b8dd6c"], "d": ["Quando o Estado sérvio se desmembrou com a derrota do Marica (Çirmen), os irmãos Jovan e Konstantin Dejanović fundaram o seu próprio principado, com centro em Velbužd (depois Köstendil), que abrangia Štip, Strumica, Doiran e a região de Köprülü. Com a morte de Jovan pouco depois, Konstantin, reconhecendo a soberania de Murad I, tornou-se vassalo otomano; o principado viveu, por este laço, de modo semi-independente. Quando Konstantin morreu em 1395, em Rovine, nas fileiras de Bajazeto I, o Relâmpago, o seu país passou sem guerra para a administração otomana e, com o nome de Kostadin-ili, tornou-se sanjaco.", "25fd68b1"]},
"OLAYLAR_P0055:1412-01-01:0":{"b": ["O déspota sérvio Stefan Lazarević toma Şehirköy (Pirot)", "87e1ecb3"], "d": ["Enquanto, no Interregno Otomano, prosseguia a luta entre Mûsâ Çelebi, que dominava a Rumélia, e o seu irmão Çelebi Mehmed, o déspota sérvio Stefan Lazarević tomou a fortaleza de Şehirköy, situada na estrada entre Niš e Sófia, e manteve-a contra o ataque de Mûsâ Çelebi. No ano seguinte, com a morte de Mûsâ, Çelebi Mehmed deixou oficialmente a fortaleza ao seu vassalo Stefan; os otomanos só retomaram Şehirköy em 1428, depois da morte de Lazarević.", "f50a8066"]},
"OLAYLAR_P0055:1538-01-01:0":{"b": ["Herceg Novi (Castelnuovo) tomada por Andrea Doria", "a8276ff1"], "d": ["Andrea Doria, comandante da armada aliada unida contra os otomanos, tomou na costa do Adriático a fortaleza de Herceg Novi (Castelnuovo), no sul da Dalmácia. No mesmo ano, na Dalmácia, também os venezianos tinham tomado algumas cidades em mãos otomanas e as forças otomanas tinham respondido com outras fortalezas. A fortaleza foi retomada um ano depois; como a soberania otomana continuava juridicamente, este período intermédio é mostrado no mapa com uma cobertura de ocupação tracejada.", "a9462728"]},
"OLAYLAR_P0055:1539-08-10:0":{"b": ["Retoma de Herceg Novi (Castelnuovo) por Barbaros Hayreddin Paxá", "1e5b49ae"], "d": ["Os otomanos, que depois da vitória de Preveza tinham obtido a supremacia também no Mediterrâneo Central, voltaram-se para a fortaleza de Nova (Castelnuovo), na costa do Adriático, que Andrea Doria tomara um ano antes. No termo da operação conduzida em conjunto por Barbaros Hayreddin Paxá e pelo bei da Bósnia Gazi Hüsrev Bey, a fortaleza foi retomada e a ocupação terminou.", "29e2c28b"]},
"OLAYLAR_P0055:1798-12-25:0":{"b": ["Campanha do Alto Egito de Desaix — a divisão francesa chega a Minya, Asyut e Girga", "8ff8e4fe"], "d": ["Enquanto Napoleão estava no Cairo, a divisão do general Desaix, perseguindo as forças mamelucas, avançou para sul no vale do Nilo: a 21 de dezembro de 1798 chegou a Minya, no dia de Natal a Asyut e a 29 de dezembro a Girga. Com esta marcha, que chegou a Assuão em fevereiro de 1799, o vale entre o Cairo e Assuão passou para o controlo francês.", "96ddd684"]},
"OLAYLAR_P0055:1799-02-18:0":{"b": ["Napoleão ocupa Arish — início da campanha da Síria", "69dc52ce"], "d": ["O exército francês, que ocupara o Egito, tomou Arish, na costa do Sinai, ao marchar para a Síria.", "8feb359c"]},
"OLAYLAR_P0055:1799-12-28:0":{"b": ["Retoma de Arish aos franceses", "c25e48a7"], "d": ["Arish, que Napoleão ocupara em fevereiro de 1799, foi retomada no fim de dezembro do mesmo ano pelo exército do grão-vizir Yûsuf Ziyâ Paxá.", "3bde687a"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Conquista da Fortaleza de Ostrovica no vale do Una", "5c6cc91b"], "d": ["Ostrovica, em mãos dos Frankapan e de outros nobres croatas, situava-se sobre uma crista escarpada que ligava as partes norte e sul do vale do Una. Passou para a administração otomana em 1523 e teve guarnição otomana até 1878. A fortaleza ganhou a sua verdadeira importância depois de Karlowitz (1699): pela proximidade da fronteira veneziana e austríaca, foi ampliada e tornou-se o centro do capitanato de Stara Ostrovica; a povoação de Kulen Vakuf foi fundada no início do século XVIII na sua base.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Conquista das fortalezas de Udbina e Krbava — a Lika entra na administração otomana", "5fe329d3"], "d": ["A planície de Krbava fora despovoada em 1524 e em Udbina restava apenas a guarnição de Karlović. Karlović obteve em abril de 1527 uma última vitória diante da fortaleza, mas no fim de maio Udbina, juntamente com as fortalezas de Mrsinj e Komić, passou para as mãos do paxá da Bósnia. No mesmo ano, a região de Gospić foi dada aos aghas Senković. A Lika e a Krbava passaram depois a fazer parte do sanjaco com centro em Obrovac que, em 1580, recebeu o nome de Kırka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Passagem definitiva de Drežnik e do condado (županija) de Drežnik para a administração otomana", "6624ad14"], "d": ["Drežnik, em mãos dos Frankapan desde 1323, fora mantida provisoriamente pelos otomanos em 1578. Em 1592, a fortaleza e todo o condado de Drežnik passaram definitivamente para a administração otomana; no mesmo ano caiu também Bihać. No século XVIII, Drežnik estava ligada ao capitanato de Ostrožac.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Tomada da Fortaleza de Cetin pelos otomanos", "98815f97"], "d": ["Cetin, fortaleza-chave na defesa da região de Slunj contra os otomanos desde meados do século XVI, passou para a administração otomana em 1636, depois de ter sido repetidamente sitiada. Este primeiro período otomano durou dois anos.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["A Fortaleza de Cetin volta para o lado Habsburgo", "690f9f84"], "d": ["Cetin, que passara em 1636 para mãos otomanas, voltou em 1638 à defesa da fronteira croata-Habsburga e assim permaneceu até 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin torna-se de novo fortaleza otomana", "e1750675"], "d": ["Cetin tornou-se de novo fortaleza otomana em 1670 e foi solidamente fortificada no século XVIII: a fortaleza medieval foi cercada por muralhas com baluartes. A fortaleza manteve até 1790 a extremidade noroeste da fronteira da Bósnia.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Perda da Lika e da Krbava — Udbina e Gospić passam para as forças fronteiriças Habsburgas", "01277a38"], "d": ["Na guerra que prosseguiu depois do desastre de Viena, as tropas fronteiriças croatas, comandadas pelo general de Karlovac Herberstein, tomaram Udbina em 1689; também Gospić saiu no mesmo ano da administração otomana. Terminou a Lika otomana, de mais de 160 anos, os lugares despovoados foram repovoados com nova população croata e Udbina foi, até à paz de Sistova (1791), uma importante fortaleza da defesa fronteiriça contra os otomanos.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Tomada de Drežnik pelos austríacos — frente ocidental da Batalha de Dubica", "05d5e5f1"], "d": ["Na guerra otomano-austríaca de 1788-1791, as forças Habsburgas tomaram Drežnik, a oeste de Bihać. Pelo artigo 4.º do Tratado de Sistova, Drežnik e Cetin permaneceram sob administração Habsburga e nunca voltaram à Bósnia.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Tomada da Fortaleza de Cetin pelos austríacos", "df182480"], "d": ["Em 1790, o exército Habsburgo atacou Cetin, Bužim e Velika Kladuša e tomou Cetin. A mobilização e o contra-ataque declarados pelo governador da Bósnia não conseguiram retomar a fortaleza; o artigo 4.º do Tratado de Sistova deixou Cetin aos Habsburgos. Os homens de fronteira bósnios retomaram a fortaleza em breves incursões em 1809 e em 1813.", "fc69baec"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraş passa para os mamelucos — o naib de Alepo Bilbân et-Tabahî retoma-a aos arménios", "03171265"], "d": ["Maraş, que estava desde 1258 nas mãos do Reino Arménio da Cilícia, passara por pouco tempo para os mamelucos em 1293, com o tratado feito pelo sultão Halil com os arménios, e depois da sua retirada voltara a cair em mãos arménias. Em 697 (1298), o naib mameluco de Alepo Bilbân et-Tabahî retomou a cidade. Maraş permaneceu depois como território mameluco até à ascensão dos Dulkadır.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["O Império Bizantino torna-se tributário dos otomanos", "615df998"], "d": ["Depois da vitória de Çirmen (1371), o imperador bizantino João V aceitou no inverno de 1372 tornar-se tributário de Murad I: pagaria um tributo anual e forneceria soldados para as campanhas do sultão. Bizâncio permaneceu desta data até 1403 como Estado vassalo ligado aos otomanos; o bloqueio de Bajazeto I, o Relâmpago, em 1391 aumentou o tributo. Depois do desastre de Ancara, o tratado de Galípoli (1403) feito com Süleyman Çelebi libertou Bizâncio do tributo; em 1424, com o tratado feito com Murad II, o tributo recomeçou.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Bajazeto I, o Relâmpago, incorpora Besni, Darende e Divriği no território otomano depois da morte de Berkuk", "8e57d7e6"], "d": ["Quando, depois da morte do sultão mameluco Berkuk (junho de 1399), os assuntos administrativos do Estado Mameluco se desordenaram, Bajazeto I, o Relâmpago, desceu à bacia do Eufrates e incorporou no território otomano, juntamente com Malatya, Besni (Behisni), Darende e Divriği. Sivas fora antes deixada aos otomanos depois da morte de Kadı Burhâneddin no verão de 1398. Divriği estava desde 1391 sob domínio mameluco e era um posto avançado ligado à província de Alepo. A administração otomana não durou aqui muito: por causa do perigo de Timur, que se aproximava, Divriği foi de novo dada aos mamelucos em 1401, e a entrada definitiva da cidade na administração otomana deu-se depois de Marj Dabiq, em 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni passa para os mamelucos durante a campanha de Timur contra Sivas e Malatya", "4853da9a"], "d": ["Besni, que Bajazeto I, o Relâmpago, tomara em 1398 com Sivas, Darende e Malatya, passou para as mãos dos mamelucos quando, em 1400, Timur tomou Sivas e Malatya. Timur tomou também Besni a 27 de setembro de 1400, depois de um violento cerco; quando se retirou da região, Besni voltou ao domínio mameluco e permaneceu mameluca (salvo um período intermédio dos Dulkadır) até que Selim I, o Severo, a tomou em agosto de 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği volta a ser dada aos mamelucos por causa do perigo de Timur", "97196b1f"], "d": ["Divriği, que Bajazeto I, o Relâmpago, tomara aos mamelucos em 1398, foi de novo deixada aos mamelucos em 1401, com a aproximação de Timur à Anatólia. Por isso, depois de Timur ter arrasado Sivas (1400), Divriği aparece no mapa com a cor mameluca; nos mesmos meses, Bajazeto tomava no leste Erzincan e Kemah, isto é, o território mameluco ficou entre os territórios otomanos do oeste (Sivas) e do nordeste (Kemah). Divriği só passou definitivamente para os otomanos depois de Marj Dabiq, em 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["O sultão mameluco Şeyh retoma Antep e Darende aos Dulkadır", "f90c9508"], "d": ["O sultão mameluco Şeyh, preocupado com a amizade dos Dulkadır com os otomanos, pôs-se em campanha em 1414; retomou Antep e Darende, que antes dera por sua vontade aos Dulkadır.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Mehmed Bey dos Dulkadıroğulları retoma Darende e incorpora também Besni nos seus territórios", "df914dcb"], "d": ["Mehmed Bey dos Dulkadıroğulları retomou em 1418 Darende, que os mamelucos tinham tomado em 1414, e incorporou também Besni nos seus territórios.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Os mamelucos derrotam os Dulkadır em Antep; Besni volta à administração mameluca (aproximado)", "72742430"], "d": ["O exército mameluco derrotou os Dulkadır em Antep em 1436 e Mehmed Bey retirou-se para Akdağ. O ano do regresso de Besni ao domínio mameluco não está escrito na fonte; Besni fora incorporada nos Dulkadır em 1418 e voltara a ser mameluca antes de Şehsuvar Bey a tomar aos mamelucos em 1465. O atlas devolve Besni aos mamelucos juntamente com esta derrota no centro vizinho de Antep (aproximação declarada).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Şehsuvar Bey dos Dulkadıroğulları toma Besni aos mamelucos (aproximado)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), nomeado bei dos Dulkadır por Maomé II, o Conquistador, tomou Besni, Gerger, Birecik e Rumkale, que estavam em mãos dos mamelucos; os mamelucos foram derrotados no outono de 1467 em Turnadağı e na primavera de 1468 perto de Antep.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["O emir Yeşbek derrota Şehsuvar Bey; Besni volta à administração mameluca (aproximado)", "4d856aee"], "d": ["Na primavera de 1471, o emir Yeşbek derrotou Şehsuvar Bey no ribeiro de Savron; os mamelucos retomaram Kadirli e Kozan. Şehsuvar foi executado em 1472 no Cairo e os mamelucos recolocaram Şahbudak à frente do beilique. Também Besni entrou, com este regresso, na administração mameluca (TDV besni: 'por volta do fim do século XV passou de novo para as mãos dos mamelucos').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["As forças de Fernando ocupam e fortificam Solnok", "6c8416e6"], "d": ["Quando os otomanos se preparavam para construir uma fortaleza em Solnok, no Tisza, as forças de Fernando I anteciparam-se: em meados de setembro de 1550 ocuparam Solnok e a fortaleza ficou defensável em meados de outubro. Assim, Solnok, que pertencia ao país de Isabel, passou para mãos Habsburgas um ano antes da passagem da Transilvânia para Fernando; os otomanos tomaram a fortaleza em 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["A Transilvânia passa para a administração dos Habsburgos: a dieta de Kolozsvár reconhece a abdicação de Isabel", "8458a566"], "d": ["Por causa do acordo de Martinuzzi com Fernando, a rainha Isabel assinou, em nome do pequeno rei János Zsigmond, a 19 de junho de 1551, na fortaleza de Szászsebes, a renúncia que lhe fora imposta. A dieta da Transilvânia, reunida a 26 de julho em Kolozsvár, reconheceu esta renúncia e a soberania do rei Fernando; o exército Habsburgo do general Castaldo entrou em Belgrado da Transilvânia (Gyulafehérvár). Assim, a Transilvânia, ligada aos otomanos, passou para uma administração Habsburga que duraria cinco anos.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Fim da administração Habsburga na Transilvânia: a Transilvânia volta a ser voivodato ligado aos otomanos", "721a482a"], "d": ["Os Habsburgos, por intermédio do padre de origem croata Martinuzzi (Fráter György), nomeado tutor de János Zsigmond por este ser menor, tentaram em 1551 dominar a Transilvânia; Belgrado da Transilvânia (Gyulafehérvár), Kaloşvar, Brassó e Segesvár permaneceram cinco anos sob administração Habsburga. Os otomanos impediram esta situação e a Transilvânia voltou a ser um voivodato tributário ligado a eles. A Transilvânia conservou depois, durante cerca de 150 anos, nos séculos XVI e XVII, o seu estatuto assente numa ampla autonomia nos assuntos internos e na vassalagem a Istambul nos assuntos externos.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt e Tokaj passam para o lado de Szapolyai", "587c782d"], "d": ["Depois do regresso de Isabel e de János Zsigmond à Transilvânia em 1556, os partidários de Szapolyai sitiaram Nagyvárad em 1556. Em 1557, os aristocratas do Alto Tisza tomaram as mais importantes fortalezas reais — Várad, Huszt e Tokaj; nas mãos de Fernando restaram apenas Gyula e Világos. Várad tornou-se depois a fortaleza do principado da Transilvânia e assim permaneceu até que os otomanos a tomaram em 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi toma Szatmár — a extremidade norte da Transilvânia passa para os Habsburgos", "2256bb27"], "d": ["Szatmár, que passara para os Habsburgos em 1561 com a mudança de lado de Balassa Menyhért, fora retomada de surpresa por Báthory István no outono de 1564 e incorporada na Transilvânia. O comandante Habsburgo Lazarus von Schwendi passou à contraofensiva em fevereiro de 1565: Tokaj caiu a 9 de fevereiro, Szerencs quatro dias depois, e Szatmár passou, quase sem resistência, para as mãos das forças imperiais.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["As forças de Bocskai tomam Szatmár", "e93b098b"], "d": ["Quando a revolta de Bocskai se estendia ao nordeste da Hungria, Gyulaffy tomou Szatmár, que sitiava, a 21 de janeiro de 1605. A paz de Viena de 23 de junho de 1606 deixou o condado de Szatmár a Bocskai vitaliciamente; como não havia herdeiro varão, com a morte de Bocskai a 29 de dezembro de 1606 o condado voltou ao reino.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Morte de Bocskai István — o condado de Szatmár volta ao reino", "3721bb9b"], "d": ["O príncipe da Transilvânia Bocskai István morreu a 29 de dezembro de 1606 em Kassa. A paz de Viena (23 de junho de 1606) deixara-lhe vitaliciamente os condados, incluindo Szatmár, para voltarem ao reino na falta de herdeiro varão; por esta disposição, o condado de Szatmár passou de novo para o reino húngaro dos Habsburgos. A Transilvânia entrou na busca de um novo príncipe.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor toma o controlo do condado de Szatmár", "80263da1"], "d": ["Com a campanha de Bethlen Gábor na Hungria no outono de 1619, o condado de Szatmár passou para o controlo do príncipe da Transilvânia; em novembro de 1619, dirigia-se ao condado por carta. O pré-acordo de 23 de janeiro de 1620 e a paz de Nikolsburg deixaram a Bethlen vitaliciamente sete condados, incluindo Szatmár. Depois da morte de Bethlen (15 de novembro de 1629), a restituição dos condados ao reino concluiu-se a 30 de março de 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Concluída a restituição ao reino dos sete condados de Bethlen Gábor", "31b5968f"], "d": ["A paz de Nikolsburg deixara a Bethlen Gábor vitaliciamente sete condados da Alta Hungria, incluindo Szatmár. Depois da morte de Bethlen a 15 de novembro de 1629, a restituição dos condados ao reino começou com a instrução de 30 de novembro de 1629 e concluiu-se a 30 de março de 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György Rákóczi I recebe Szatmár", "f398635b"], "d": ["Na campanha de 1644 do príncipe da Transilvânia György Rákóczi I, a guarnição alemã de Szatmár passou para o serviço de Rákóczi e a fortaleza passou para as mãos da Transilvânia. A paz de Linz de 16 de dezembro de 1645 deixou a fortaleza aos herdeiros de Rákóczi enquanto um Rákóczi estivesse no trono da Transilvânia.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Perda de Nitra — De Souches retoma a fortaleza", "c71bf012"], "d": ["Nitra, que depois da conquista de Uyvar, em 1663, se rendera após breve resistência, foi sitiada a 15 de abril de 1664 pelo comandante imperial De Souches; a fortaleza rendeu-se a 3 de maio de 1664. Como o Tratado de Vasvár deixou os lugares tomados no estado em que se encontravam, Uyvar ficou com os otomanos e Nitra permaneceu em mãos Habsburgas.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Perda de Léva", "f311920e"], "d": ["De Souches, depois de Nitra, sitiou Léva a 9 de junho de 1664; a 13 de junho foi assinada a capitulação e a fortaleza estava a 14 de junho em mãos das forças imperiais. A batalha de Léva (Garamszentbenedek) de 19 de julho de 1664 não mudou o dono; terminou com a manutenção de Léva e de Nitra pelos Habsburgos.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroshenko entrega Chyhyryn a Samoilovych", "3b538237"], "d": ["O hetman da Margem Direita, sob proteção otomana, Petro Doroshenko, entregou a capital, Chyhyryn, a 19 de setembro de 1676, ao hetman da Margem Esquerda Samoilovych e às forças russas. Os otomanos depuseram Doroshenko e puseram no seu lugar Yuri Khmelnytsky; o cerco de 1677 para expulsar a guarnição russa de Chyhyryn fracassou e a fortaleza só foi tomada a 21 de agosto de 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Entrega das fortalezas do Banat da Transilvânia (Timişoara, Lippa, Lugos, Karánsebes) ao rei Fernando da Hungria", "0e354976"], "d": ["Em 1551, o exército Habsburgo comandado pelo general Castaldo entrou na Transilvânia; a rainha Isabel e o seu filho foram obrigados a renunciar aos seus direitos ao trono da Hungria. Martinuzzi, com a aprovação de Castaldo, enviou em meados de julho de 1551 Báthory Endre a receber, em nome de Fernando, as fortalezas de Timişoara, Lippa, Solymos, Karánsebes, Lugos, Becse, Becskerek e Csanád. As fortalezas do sul da Transilvânia, sob proteção otomana, passaram assim para mãos Habsburgas; as campanhas do Legislador de 1551-1552 são a resposta a isso.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Nomeação de Petrovics Péter como sancakbeyi de Lugos e Karánşebeş", "bcbe73e4"], "d": ["A pedido insistente de Isabel e de Petrovics, o Legislador decidiu fazer regressar o pequeno János Zsigmond à Transilvânia. Por carta escrita de Alepo a 7 de abril de 1554, ordenou à Transilvânia que levasse a criança de volta ao seu país; mandou também os voivodas da Valáquia e da Moldávia ajudarem neste assunto Petrovics, que nomeou nessa ocasião sancakbeyi de Lugos e Karánşebeş. Lugos, conquistada em 1552, foi assim dada a Petrovics como sanjaco otomano.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Levantamento do cerco de Lippa — ataque do bân de Lugos a Timişoara", "be03430e"], "d": ["Na primavera de 1596, o paxá de Timişoara sitiou Lippa. Na noite de 10 para 11 de maio, por ordem do bân de Lugos da Transilvânia, Palatics György, os soldados de Buday György invadiram e incendiaram os arrabaldes de Timişoara; o facto de Borbély György ter feito disparar na fortaleza todos os seus canhões fez também o paxá crer que chegara socorro. O paxá retirou-se a 11 de maio de diante de Lippa e correu a proteger o seu próprio centro. Lugos estava então em mãos do Principado da Transilvânia.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Ocupação de Orsova pelas forças austríacas comandadas por Veterani", "1b4a4f6c"], "d": ["Na campanha de 1688, o general Veterani, depois de tomar Karánsebes, marchou sobre Orsova e ocupou-a também. A fonte não tem o dia da ocupação; usou-se a base do ano, 1 de janeiro de 1688.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Retoma de Orsova por Thököly e pelas forças otomanas", "c5645da9"], "d": ["Sobre Orsova, ocupada por Veterani em 1688, marcharam, depois da tomada de Vetislan, Thököly e os paxás otomanos. Depois de escaramuças sem importância, Thököly entrou em Orsova a 15 de julho de 1689. Heissler, que chegou com a notícia do perigo, vendo que a força à sua frente estava bem equipada de munições e navios, retirou-se para defender a Transilvânia. Em agosto, também o ataque de Herbeville diante da cidade não conseguiu retomar Orsova.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["O sanjaco de Lugos entra na ocupação Habsburga (1691-1695)", "c8bcd6bd"], "d": ["O sanjaco de Lugos permaneceu sob ocupação Habsburga (alemã) de 1691 a 1695; Mustafa II reconquistou-o a 22 de setembro de 1695. No registo antigo, o período de 1689-1695 era um vazio declarado; a fatia 1691-1695 passa a ser pintada como Habsburga, e 1689-1691 continua vazio. A data foi tomada apenas como ano.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-13:0":{"b": ["A fortaleza de Lugos entra na administração Habsburga", "6a9d401f"], "d": ["A fortaleza de sanjaco de Lugoj, ligada ao eyalet de Tımışvar, estava em mãos otomanas desde 1695; com a rendição do centro do eyalet no termo do cerco de 1716, foi cedida à Monarquia dos Habsburgos. O registo antigo punha a passagem em 1 de janeiro de 1716, a base do ano.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Tomada de Orsova pelo exército Habsburgo (campanha de 1717)", "7a4faffe"], "d": ["Na campanha de 1717, o general Splényi chegou diante de Orsova a 27 de agosto e tomou facilmente a cidade; Orsova, que Mercy não conseguira tomar em 1716, passou assim para mãos Habsburgas. Como os favos das margens do Danúbio à sua volta (incluindo o troço de Đerdap, do lado da Sérvia) estão ligados ao ponto de povoamento mais próximo, Orsova, são pintados com o seu dono. A data foi tomada apenas como ano; o dia exato não está confirmado.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Passagem da palanka de Orsova para os otomanos — o guarda retira-se para Ada Kale", "de759b16"], "d": ["Na abertura da campanha de 1738, Hacı Mehmed Paxá, guarda de Vidin, atacou o baluarte de Erzsébet, no Danúbio. Na tarde de 8 de maio, uma força de 4-5 mil sipahis marchou da margem esquerda do Danúbio para Orsova e atacou a palanka de Orsova; o guarda austríaco, que sofreu cerca de cem baixas, retirou-se para Nova Orsova, isto é, a fortaleza insular de Ada Kale. Depois dos combates de Mehadia em julho, também Ada Kale passou para mãos otomanas em agosto de 1738; o Tratado de Belgrado de 1739 reconheceu a situação.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II toma Alacahisar, Niš e Şehirköy voltam aos otomanos", "54af926a"], "d": ["Depois da morte sem herdeiros do déspota sérvio Stefan Lazarević (1427), Murad II, alegando ser o legítimo herdeiro da Sérvia com base no casamento de Bajazeto I, o Relâmpago, com a princesa sérvia, pôs-se em movimento e tomou Alacahisar (1428). No mesmo ano, depois da morte de Lazarević, os otomanos retomaram também a fortaleza de Şehirköy — a cidade fora tomada por Stefan em 1412 e defendida contra Mûsâ Çelebi. Segundo o artigo Niş do TDV, os otomanos retomaram Niš no mesmo ano (831/1428). Assim, a linha que liga os vales do Grande Morava e do Nišava passou para o controlo otomano.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["O exército cruzado toma Şehirköy — ramo do Nišava da 'Longa Campanha'", "fdf6140c"], "d": ["O exército cruzado, liderado pelo rei Ladislau e pelo déspota sérvio Đurađ Branković, tomou Şehirköy em 1443. Na continuação da mesma campanha, as forças otomanas serão derrotadas em novembro no desfiladeiro de İzladi. Şehirköy foi de novo dada aos sérvios por Murad II depois do Tratado de Szeged (1444), mas passou para os otomanos em 1456, depois da morte de Đurađ Branković.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Estabelecido o domínio otomano definitivo na região de Alacahisar", "9715382a"], "d": ["Alacahisar, deixada a Branković no termo do tratado feito em 1444 com os delegados húngaros, voltou ao domínio turco nos anos que se seguiram à vitória de Varna. Esta segunda conquista da cidade não é documentada por um registo de guerra, mas por um registo fiscal: os registos de timar de algumas aldeias ligadas a Alacahisar datam do fim de 1453/início de 1454; contudo, é apenas um testemunho de aldeias — em 1454 as forças otomanas foram derrotadas nos arredores de Alacahisar e em 1455 Alacahisar foi deixada a Branković como fronteira. Segundo o TDV, o domínio otomano definitivo na região foi estabelecido em 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Fundação do Despotado da Moreia — Manuel Cantacuzeno em Mistra", "87660b82"], "d": ["O imperador bizantino João Cantacuzeno deu ao seu filho Manuel uma circunscrição administrativa separada na Moreia; assim nasceu o Despotado da Moreia, com centro em Mistra. Manuel governou até 1380; neste período, a cultura e a arte bizantinas floresceram em especial em Mistra. O despotado durou até à conquista de Maomé II, o Conquistador, em 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["O déspota Constantino toma Patras aos francos", "cb0dd18c"], "d": ["Constantino, déspota da Moreia (em 1449, último imperador bizantino), retomou Patras aos latinos; assim, este importante porto do noroeste da península foi também incorporado no despotado. Patras entrou no domínio otomano em 1458, na campanha da Moreia de Maomé II, o Conquistador.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić-Kosača 'Duque de São Sava' — nascimento da Herzegovina", "cc67061f"], "d": ["Stjepan Vukčić-Kosača, que reunira Hum e Trebinje num só beilique, revoltou-se contra o rei da Bósnia e proclamou-se 'Herzog (duque) de São Sava'; o título foi dado em 1448 pelo imperador Frederico III. O nome Herzegovina ('terra do Herzog') vem deste título. A Herzegovina passou a pouco e pouco para os otomanos a partir de 1466, tornou-se sanjaco em 1470; os seus territórios restantes foram anexados no início de 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Paz de Cracóvia — o Estado da ordem germânica transforma-se no Ducado da Prússia", "78666ddd"], "d": ["Alberto de Brandemburgo, grão-mestre dos Cavaleiros Teutónicos, não encontrando ajuda contra a Polónia, assinou a Paz de Cracóvia. O Estado da ordem (Ordensstaat) tornou-se, sob a suserania da Polónia, um ducado hereditário e secular, passado para a dinastia de Brandemburgo. O centro era Königsberg; Alberto fundou aí, em 1544, a Universidade Albertina. O ducado transformou-se em 1701 em Reino da Prússia.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proclamação da República da Áustria — fim da monarquia dos Habsburgos", "c84f316c"], "d": ["No dia seguinte àquele em que o imperador Carlos I, a 11 de novembro, se retirou dos assuntos do Estado, a Assembleia Nacional Provisória aprovou a lei sobre a forma do Estado e do governo e foi proclamada a república. O lugar da Áustria dos Habsburgos foi tomado pela Primeira República, com centro em Viena.", "f747ce09"]}
});
